function chartsAvailable(canvasId, fallbackMsg) {
  const canvas = $(canvasId);
  if (!canvas) return false;
  const wrap = canvas.parentElement;
  let msg = wrap.querySelector('.chart-fallback');
  if (typeof Chart === 'undefined') {
    if (!msg) {
      msg = document.createElement('div');
      msg.className = 'chart-fallback';
      msg.innerHTML = `<i class="fa-solid fa-chart-line"></i> ${fallbackMsg || 'Charts need an internet connection to load the chart library.'}`;
      wrap.appendChild(msg);
    }
    canvas.style.display = 'none';
    return false;
  }
  if (msg) msg.remove();
  canvas.style.display = '';
  return true;
}

const CHART_MODES = {
  temp: { type: 'line', color: ['#38bdf8', '#0284c7'], label: () => `Temperature (°${AppState.unit.toUpperCase()})`, value: h => +cToUnit(h.temp).toFixed(1), suffix: () => `°${AppState.unit.toUpperCase()}` },
  rain: { type: 'bar', color: ['#06b6d4', '#0891b2'], label: () => `Rainfall (${AppState.rainUnit})`, value: h => +rainValue(h.rainAmount).toFixed(AppState.rainUnit === 'in' ? 2 : 1), suffix: () => ` ${AppState.rainUnit}`, extra: true },
  wind: { type: 'line', color: ['#2dd4bf', '#0d9488'], label: () => `Wind (${WIND_UNITS[AppState.windUnit].label})`, value: h => +windValue(h.wind).toFixed(1), suffix: () => ` ${WIND_UNITS[AppState.windUnit].label}` },
  humidity: { type: 'line', color: ['#818cf8', '#6366f1'], label: () => 'Humidity (%)', value: h => h.humidity, suffix: () => '%' }
};

function renderHourlyChart(hourly) {
  if (!hourly || !hourly.length || !chartsAvailable('hourlyWeatherChart')) return;
  const hours = hourly.slice(0, 24);
  const mode = CHART_MODES[AppState.activeChartMode] || CHART_MODES.temp;
  const t = chartTheme();
  const color = t.dark ? mode.color[0] : mode.color[1];
  // Dynamic 8: same chart type → animate to the new location's data instead of rebuilding
  const chartKey = `${AppState.activeChartMode}|${t.dark}|${AppState.unit}|${AppState.windUnit}|${AppState.rainUnit}|${AppState.timeFormat || '12'}`;
  const old = AppState.charts.hourly;
  if (old && old.$key === chartKey && old.data.datasets.length === (mode.extra ? 2 : 1)) {
    old.data.labels = hours.map((h, i) => i === 0 ? 'Now' : hourLabel(h.isoTime));
    old.data.datasets[0].data = hours.map(mode.value);
    old.data.datasets[0].label = mode.label();
    if (mode.extra) old.data.datasets[1].data = hours.map(h => h.rainProb);
    old.update();
    return;
  }
  if (old) old.destroy();

  const datasets = [{
    label: mode.label(), data: hours.map(mode.value), type: mode.type, yAxisID: 'y',
    borderColor: color, backgroundColor: mode.type === 'bar' ? `${color}99` : `${color}26`,
    fill: mode.type !== 'bar', tension: 0.35, borderWidth: 2.5, pointBackgroundColor: color, pointRadius: 3, pointHoverRadius: 6, borderRadius: 4, order: 2
  }];
  if (mode.extra) {
    datasets.push({
      label: 'Chance of rain (%)', data: hours.map(h => h.rainProb), type: 'line', yAxisID: 'y1',
      borderColor: '#a78bfa', backgroundColor: 'transparent', borderDash: [5, 4], borderWidth: 2, pointRadius: 0, tension: 0.35, order: 1
    });
  }
  AppState.charts.hourly = new Chart($('hourlyWeatherChart'), {
    type: mode.type,
    data: { labels: hours.map((h, i) => i === 0 ? 'Now' : hourLabel(h.isoTime)), datasets },
    options: {
      responsive: true, maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: !!mode.extra, labels: { color: t.text, boxWidth: 12 } },
        tooltip: { ...t.tooltip, callbacks: { label: (ctx) => ctx.dataset.yAxisID === 'y1' ? ` ${ctx.parsed.y}% chance of rain` : ` ${ctx.parsed.y}${mode.suffix()}` } }
      },
      scales: {
        x: { grid: { color: t.grid }, ticks: { color: t.text, font: { size: 11 }, maxRotation: 0, autoSkip: true, maxTicksLimit: 12 } },
        y: { grid: { color: t.grid }, beginAtZero: AppState.activeChartMode !== 'temp', ticks: { color: t.text, font: { size: 11 } } },
        y1: { display: !!mode.extra, position: 'right', min: 0, max: 100, grid: { display: false }, ticks: { color: t.text, callback: v => `${v}%` } }
      }
    }
  });
  AppState.charts.hourly.$key = chartKey;
  if (window.V6) V6.safe('hourly-chart', () => V6.onHourlyChart());
}

function rerenderCharts() {
  const data = weatherFor(activeLoc());
  if (data) renderHourlyChart(data.hourly);
  const hist = AppState.historyCache[activeLoc().key];
  if (hist) renderHistoricalChart(hist);
  if (!$('compare-modal-backdrop').classList.contains('hidden')) renderComparison();
}

// ==========================================================================
// 17. All-district grid
// ==========================================================================
function render25DistrictsGrid() {
  const grid = $('districts-grid');
  const cache = AppState.districtWeatherCache;
  if (!Object.keys(cache).length) {
    grid.innerHTML = Array.from({ length: 10 }, () => '<div class="district-card skeleton-card"><div class="skeleton-line w60"></div><div class="skeleton-line w40"></div><div class="skeleton-line w80 tall"></div><div class="skeleton-line w100"></div></div>').join('');
    return;
  }
  grid.innerHTML = '';
  const list = SRI_LANKA_DISTRICTS.filter(d => AppState.selectedProvince === 'all' || d.province.toLowerCase() === AppState.selectedProvince.toLowerCase());
  const val = (d, k) => (cache[d.name] || {})[k] ?? 0;
  list.sort((a, b) => {
    switch (AppState.districtSort) {
      case 'temp-high': return val(b, 'currentTemp') - val(a, 'currentTemp');
      case 'temp-low': return val(a, 'currentTemp') - val(b, 'currentTemp');
      case 'rain': return val(b, 'rainProb') - val(a, 'rainProb');
      case 'wind': return val(b, 'windSpeed') - val(a, 'windSpeed');
      default: return a.name.localeCompare(b.name);
    }
  });

  list.forEach(district => {
    const data = cache[district.name];
    if (!data) return;
    const isSelected = district.name === AppState.selectedDistrict.name;
    const isFav = AppState.favorites.includes(district.name);
    const w = getWeatherInfo(data.weatherCode, data.isDay);
    const card = document.createElement('div');
    card.className = `district-card ${isSelected ? 'active-selected' : ''}`;
    card.setAttribute('role', 'button');
    card.setAttribute('tabindex', '0');
    card.setAttribute('aria-label', `${district.name}: ${formatTemp(data.currentTemp)}, ${w.label}`);
    card.innerHTML = `
      <div class="d-header">
        <div>
          <div class="d-name">${district.name}${isFav ? ' <i class="fa-solid fa-star text-amber d-fav" title="Favourite"></i>' : ''}</div>
          <div class="d-si" lang="si">${district.sinhala}</div>
          <div class="d-province">${district.province} Province</div>
        </div>
        <i class="fa-solid ${w.icon} d-icon" style="color:${w.color}"></i>
      </div>
      <div class="d-body">
        <div class="d-temp">${formatTemp(data.currentTemp)}</div>
        <div class="d-condition">${w.label}</div>
      </div>
      <div class="d-footer">
        <span title="Humidity"><i class="fa-solid fa-droplet text-blue"></i> ${data.humidity}%</span>
        <span title="Wind"><i class="fa-solid fa-wind text-teal"></i> ${formatWind(data.windSpeed)}</span>
        <span title="Chance of rain today"><i class="fa-solid fa-umbrella text-indigo"></i> ${Math.round(data.rainProb)}%</span>
      </div>`;
    card.addEventListener('click', () => selectDistrictAndZoom(district));
    card.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectDistrictAndZoom(district); }
    });
    grid.appendChild(card);
  });
}

// ==========================================================================
// 18. Smart search with autocomplete + GPS (Feature 1)
// ==========================================================================
const Search = { results: [], highlighted: -1, query: '', onlineToken: 0 };

// --- Gazetteer: every city, town, suburb and village (≈35,000 places), loaded in the background ---
const Gazetteer = {
  status: 'idle', places: [], count: 0, promise: null, wordIndex: null,
  load() {
    if (this.status === 'ready') return Promise.resolve(this);
    if (this.promise) return this.promise;
    this.status = 'loading';
    this.promise = new Promise((resolve, reject) => {
      const done = () => {
        try { this.index(window.SL_GAZETTEER); this.status = 'ready'; resolve(this); }
        catch (e) { this.status = 'error'; this.promise = null; reject(e); }
        if (Search.query && !$('search-suggestions').classList.contains('hidden')) handleSearchInput();
      };
      if (window.SL_GAZETTEER) { done(); return; }
      const script = document.createElement('script');
      script.src = 'places-lk.js';
      script.async = true;
      script.onload = done;
      script.onerror = () => {
        this.status = 'error'; this.promise = null;
        reject(new Error('Could not load the list of towns and villages'));
        if (Search.query) handleSearchInput();
      };
      document.head.appendChild(script);
    });
    return this.promise;
  },
  index(G) {
    if (!G || !G.rows) throw new Error('Gazetteer data missing');
    const rows = G.rows.split('\n');
    this.places = rows.map((row, i) => {
      const f = row.split('|');
      const alts = f[9] ? f[9].split('~') : [];
      return {
        id: i, name: f[0], lat: +f[1], lon: +f[2], district: G.districts[+f[3]], type: f[4] || 'v',
        ds: f[5] ? G.ds[+f[5]] : '', si: f[6] || '', ta: f[7] || '', pc: f[8] || '', alts,
        k: searchKey(f[0]), lname: ` ${f[0].toLowerCase()}`, ph: phoneticKey(f[0]), ak: alts.map(searchKey)
      };
    });
    this.count = this.places.length;
    delete window.SL_GAZETTEER;
  },
  // Places big enough to be recognised inside free text (used by the assistant)
  findInText(text) {
    if (this.status !== 'ready') return [];
    if (!this.wordIndex) {
      this.wordIndex = new Map();
      this.places.forEach(p => {
        if (!'kcstp'.includes(p.type) || p.k.length < 4) return;
        if (!this.wordIndex.has(p.k)) this.wordIndex.set(p.k, p);
      });
    }
    const words = normalise(text).split(/\s+/).filter(Boolean);
    const hits = [];
    for (let i = 0; i < words.length; i++) {
      for (let n = 3; n >= 1; n--) {
        if (i + n > words.length) continue;
        const k = searchKey(words.slice(i, i + n).join(''));
        const p = this.wordIndex.get(k);
        if (p && !STOP_WORDS.has(k)) { hits.push([i, p]); i += n - 1; break; }
      }
    }
    return hits;
  }
};
const STOP_WORDS = new Set(['will', 'rain', 'what', 'wear', 'today', 'weather', 'there', 'where', 'when', 'this', 'that', 'with', 'about', 'evening', 'morning', 'night', 'tomorrow', 'week', 'beach', 'compare', 'should', 'which', 'hottest', 'coolest', 'climb', 'safe', 'hike', 'like', 'into', 'from', 'than', 'have', 'here', 'sea', 'water', 'town', 'city', 'village', 'hill', 'park']);

function searchKey(s) { return String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, ''); }
// Sinhala/Tamil place names are spelt many ways in English (Dehiwala/Dehiwela, Kithagama/Kitagama, Vavuniya/Wavuniya)
function phoneticKey(s) {
  return searchKey(s).replace(/[0-9]/g, '')
    .replace(/th/g, 't').replace(/dh/g, 'd').replace(/kh/g, 'k').replace(/bh/g, 'b').replace(/ph/g, 'p').replace(/gh/g, 'g').replace(/sh/g, 's').replace(/ch/g, 'c')
    .replace(/v/g, 'w').replace(/z/g, 's').replace(/y/g, 'i').replace(/[ae]/g, 'a').replace(/[ou]/g, 'u').replace(/(.)\1+/g, '$1');
}

function initSearch() {
  const input = $('district-search');
  input.addEventListener('input', handleSearchInput);
  input.addEventListener('focus', () => { Gazetteer.load().catch(() => {}); if (input.value.trim()) handleSearchInput(); });
  input.addEventListener('keydown', handleSearchKeys);
  $('clear-search').addEventListener('click', () => { clearSearch(); input.focus(); });
  $('geo-location-btn').addEventListener('click', useMyLocation);
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.search-bar-wrapper')) $('search-suggestions').classList.add('hidden');
  });
  // Press "/" anywhere to jump to search
  document.addEventListener('keydown', (e) => {
    if (e.key === '/' && !['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName)) {
      e.preventDefault();
      input.focus();
    }
  });
}

function normalise(s) { return String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\u0D80-\u0DFF\u0B80-\u0BFF ]/g, ''); }

const TYPE_BONUS = { c: 70, k: 55, t: 50, s: 45, p: 40, a: 25, v: 15, g: 6, e: 6, l: 0 };

function placeSub(p) {
  const d = findDistrict(p.district);
  return [p.ds && p.ds !== p.name ? `${p.ds} DS` : '', `${p.district} District`, d ? `${d.province} Province` : '', p.pc ? `📮 ${p.pc}` : ''].filter(Boolean).join(' · ');
}

function searchAll(query) {
  const raw = query.trim();
  const q = normalise(raw).trim();
  const qk = searchKey(raw);
  if (!q && !raw) return [];
  const isNative = /[\u0D80-\u0DFF\u0B80-\u0BFF]/.test(raw);
  const results = [];

  SRI_LANKA_DISTRICTS.forEach(d => {
    const name = normalise(d.name);
    let score = -1;
    if (q && name === q) score = 1000;
    else if (q && name.startsWith(q)) score = 900;
    else if (isNative && (d.sinhala.startsWith(raw) || (d.tamil || '').startsWith(raw))) score = 880;
    else if (q.length >= 3 && name.includes(q)) score = 500;
    else if (q.length >= 3 && normalise(d.province).startsWith(q)) score = 300;
    if (score >= 0) results.push({ type: 'district', district: d, score, title: `${d.name} District`, sub: `${d.province} Province · whole district`, si: d.sinhala, badge: 'District' });
  });

  SEARCH_PLACES.forEach(p => {
    const k = searchKey(p.name);
    let score = -1;
    if (qk && k === qk) score = 820;
    else if (qk && k.startsWith(qk)) score = 640;
    else if (qk.length >= 3 && ` ${p.name.toLowerCase()}`.includes(` ${raw.toLowerCase()}`)) score = 560;
    else if (qk.length >= 3 && k.includes(qk)) score = 430;
    else if (isNative && p.sinhala && p.sinhala.startsWith(raw)) score = 700;
    if (score >= 0 && isFinite(p.lat)) {
      const place = { name: p.name, lat: p.lat, lon: p.lon, district: p.district, type: 'p', si: p.sinhala, typeLabel: 'Popular spot' };
      results.push({ type: 'place', place, district: findDistrict(p.district), score: score + 45, title: p.name, sub: placeSub(place), si: p.sinhala, badge: 'Popular' });
    }
  });

  if (Gazetteer.status === 'ready' && (qk.length >= 2 || isNative)) {
    const qph = phoneticKey(raw);
    const qlow = ` ${raw.toLowerCase()}`;
    const digits = /^\d{3,5}$/.test(raw);
    for (const p of Gazetteer.places) {
      let score = -1;
      if (digits) { if (p.pc && p.pc.startsWith(raw)) score = 700; }
      else if (isNative) { if (p.si.startsWith(raw) || p.ta.startsWith(raw)) score = 640; else if (p.si.includes(raw)) score = 420; }
      else if (p.k === qk) score = 800;
      else if (p.k.startsWith(qk)) score = 600 - Math.min(90, (p.k.length - qk.length) * 3);
      else if (qk.length >= 4 && p.ak.includes(qk)) score = 760;
      else if (qk.length >= 3 && p.lname.includes(qlow)) score = 560;
      else if (qk.length >= 3 && p.ak.some(a => a.startsWith(qk))) score = 440;
      else if (qk.length >= 4 && qph.length >= 3 && p.ph.startsWith(qph)) score = 400 - Math.min(60, (p.ph.length - qph.length) * 3);
      else if (qk.length >= 4 && p.k.includes(qk)) score = 260;
      if (score < 0) continue;
      score += TYPE_BONUS[p.type] || 0;
      results.push({ type: 'place', place: p, district: findDistrict(p.district), score, title: p.name, sub: placeSub(p), si: p.si || p.ta, badge: PLACE_TYPES[p.type] || 'Place' });
    }
  }

  // Best first; drop near-duplicates (same name within ~3 km)
  results.sort((a, b) => b.score - a.score || a.title.length - b.title.length || a.title.localeCompare(b.title));
  const out = [];
  for (const r of results) {
    if (r.type === 'place' && out.some(o => o.type === 'place' && searchKey(o.title) === searchKey(r.title) && haversineKm(o.place.lat, o.place.lon, r.place.lat, r.place.lon) < 3)) continue;
    out.push(r);
    if (out.length >= 12) break;
  }
  return out;
}

function handleSearchInput() {
  const query = $('district-search').value;
  Search.query = query.trim();
  Search.onlineToken++;
  $('clear-search').classList.toggle('hidden', !query);
  if (!query.trim()) { $('search-suggestions').classList.add('hidden'); return; }
  if (Gazetteer.status === 'idle') Gazetteer.load().catch(() => {});
  Search.results = searchAll(query);
  if (query.trim().length >= 3) {
    Search.results.push({ type: 'online', score: 0, title: `Search online maps for “${query.trim()}”`, sub: 'Can’t find your village? Look it up on OpenStreetMap (needs internet)' });
  }
  Search.highlighted = Search.results.length ? 0 : -1;
  renderSuggestions(query);
}

function highlightMatch(text, query) {
  const i = text.toLowerCase().indexOf(query.trim().toLowerCase());
  if (i < 0 || !query.trim()) return escapeHtml(text);
  return `${escapeHtml(text.slice(0, i))}<mark>${escapeHtml(text.slice(i, i + query.trim().length))}</mark>${escapeHtml(text.slice(i + query.trim().length))}`;
}

function suggestionIcon(r) {
  if (r.type === 'district') return 'fa-map';
  if (r.type === 'online') return 'fa-globe';
  const t = r.place.type;
  return { c: 'fa-city', k: 'fa-building', t: 'fa-building', s: 'fa-house-chimney', v: 'fa-house', g: 'fa-house', e: 'fa-leaf', p: 'fa-star', l: 'fa-location-dot', a: 'fa-landmark', o: 'fa-location-dot' }[t] || 'fa-location-dot';
}

function renderSuggestions(query) {
  const box = $('search-suggestions');
  box.innerHTML = '';
  const realResults = Search.results.filter(r => r.type !== 'online');
  if (!realResults.length && Gazetteer.status !== 'loading') {
    const empty = document.createElement('div');
    empty.className = 'suggestion-item empty';
    empty.innerHTML = `<span class="suggestion-sub"><i class="fa-solid fa-circle-info"></i> No district, town or village in our list matches “${escapeHtml(query)}”. Check the spelling (e.g. “Kithagama” or “Kitagama”), try the Sinhala name, or search the online map below.</span>`;
    box.appendChild(empty);
  }
  Search.results.forEach((r, i) => {
    let badge;
    if (r.type === 'district') {
      const data = AppState.districtWeatherCache[r.district.name];
      badge = data ? `<i class="fa-solid ${getWeatherInfo(data.weatherCode, data.isDay).icon}" style="color:${getWeatherInfo(data.weatherCode, data.isDay).color}"></i> ${formatTemp(data.currentTemp)}` : 'District';
    } else if (r.type === 'place') {
      const px = AppState.placeWeatherCache[placeKey(r.place)];
      badge = px && !px.approx ? `<i class="fa-solid ${getWeatherInfo(px.weatherCode, px.isDay).icon}" style="color:${getWeatherInfo(px.weatherCode, px.isDay).color}"></i> ${formatTemp(px.currentTemp)}` : escapeHtml(r.badge);
    } else {
      badge = '<i class="fa-solid fa-arrow-up-right-from-square"></i>';
    }
    const item = document.createElement('div');
    item.className = `suggestion-item ${r.type === 'online' ? 'online' : ''} ${i === Search.highlighted ? 'highlighted' : ''}`;
    item.dataset.idx = i;
    item.setAttribute('role', 'option');
    item.setAttribute('aria-selected', String(i === Search.highlighted));
    item.innerHTML = `
      <div class="suggestion-main">
        <span class="suggestion-title"><i class="fa-solid ${suggestionIcon(r)} suggestion-type"></i>${r.type === 'online' ? escapeHtml(r.title) : highlightMatch(r.title, query)}${r.si ? `<span class="suggestion-si" lang="si">${escapeHtml(r.si)}</span>` : ''}</span>
        <span class="suggestion-sub">${escapeHtml(r.sub)}</span>
      </div>
      <span class="suggestion-badge">${badge}</span>`;
    item.addEventListener('mousedown', (e) => e.preventDefault());
    item.addEventListener('click', () => chooseSearchResult(r));
    box.appendChild(item);
  });
  if (Gazetteer.status === 'loading') {
    const note = document.createElement('div');
    note.className = 'suggestion-item empty';
    note.innerHTML = '<span class="suggestion-sub"><i class="fa-solid fa-spinner fa-spin"></i> Loading 35,000+ Sri Lankan towns, suburbs and villages…</span>';
    box.appendChild(note);
  } else if (Gazetteer.status === 'error') {
    const note = document.createElement('div');
    note.className = 'suggestion-item empty';
    note.innerHTML = '<span class="suggestion-sub"><i class="fa-solid fa-triangle-exclamation text-amber"></i> The village list could not be loaded (places-lk.js). Districts and popular spots still work.</span>';
    box.appendChild(note);
  }
  box.classList.remove('hidden');
}

function handleSearchKeys(e) {
  const box = $('search-suggestions');
  if (e.key === 'Escape') { clearSearch(); e.target.blur(); return; }
  if (box.classList.contains('hidden') || !Search.results.length) {
    if (e.key === 'Enter') handleSearchInput();
    return;
  }
  const items = [...box.querySelectorAll('.suggestion-item[data-idx]')];
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    const n = Search.results.length;
    Search.highlighted = (Search.highlighted + (e.key === 'ArrowDown' ? 1 : -1) + n) % n;
    items.forEach((c, i) => {
      c.classList.toggle('highlighted', i === Search.highlighted);
      c.setAttribute('aria-selected', String(i === Search.highlighted));
      if (i === Search.highlighted) c.scrollIntoView({ block: 'nearest' });
    });
  } else if (e.key === 'Enter') {
    e.preventDefault();
    const r = Search.results[Math.max(0, Search.highlighted)];
    if (r) chooseSearchResult(r);
  }
}

function chooseSearchResult(r) {
  if (r.type === 'online') { searchOnline(Search.query); return; }
  if (r.type === 'district') {
    selectDistrictAndZoom(r.district, { toast: false });
    showToast(`${r.district.name} District · ${r.district.sinhala}`, 'success', 2500);
  } else {
    selectPlace(r.place);
  }
  clearSearch();
  $('district-search').blur();
  $('interactive-map-section').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// Online fallback for tiny villages that aren't in the offline list (OpenStreetMap Nominatim, then Open-Meteo geocoding)
async function searchOnline(query) {
  const box = $('search-suggestions');
  if (!query) return;
  if (navigator.onLine === false) { showToast('You are offline – the online map search needs internet.', 'warning'); return; }
  const token = ++Search.onlineToken;
  box.innerHTML = `<div class="suggestion-item empty"><span class="suggestion-sub"><i class="fa-solid fa-spinner fa-spin"></i> Searching OpenStreetMap for “${escapeHtml(query)}” in Sri Lanka…</span></div>`;
  box.classList.remove('hidden');
  let places = [];
  try {
    const list = await fetchJSON(`https://nominatim.openstreetmap.org/search?format=jsonv2&countrycodes=lk&addressdetails=1&limit=10&accept-language=en&q=${encodeURIComponent(query)}`, { timeout: 12000, retries: 0 });
    const rank = (it) => ({ place: 0, boundary: 1, landuse: 3, amenity: 4, tourism: 2, natural: 2 }[it.category] ?? 5);
    const sorted = (list || []).filter(it => !['highway', 'railway', 'shop', 'building', 'office'].includes(it.category)).sort((x, y) => rank(x) - rank(y));
    places = (sorted.length ? sorted : (list || [])).map(item => {
      const lat = +item.lat, lon = +item.lon;
      const a = item.address || {};
      const district = findDistrict(a.state_district) || findDistrict(a.county) || districtAt(lat, lon);
      const typeLabel = String(item.addresstype || item.type || 'place').replace(/_/g, ' ');
      return {
        name: item.name || String(item.display_name || query).split(',')[0], lat, lon, district: district.name, type: 'o',
        typeLabel: typeLabel.charAt(0).toUpperCase() + typeLabel.slice(1), ds: '', pc: a.postcode || '',
        near: [a.suburb, a.village, a.town, a.city].filter(Boolean).find(n => n !== item.name) || ''
      };
    });
  } catch (err) {
    console.warn('Nominatim failed, trying Open-Meteo geocoding', err);
    try {
      const json = await fetchJSON(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(query)}&count=10&language=en&countryCode=LK`, { timeout: 10000, retries: 0 });
      places = (json.results || []).map(r => ({
        name: r.name, lat: r.latitude, lon: r.longitude, district: (findDistrict(r.admin2) || districtAt(r.latitude, r.longitude)).name,
        type: 'o', typeLabel: 'Place', ds: r.admin3 || '', pc: (r.postcodes || [])[0] || ''
      }));
    } catch (err2) {
      if (token !== Search.onlineToken) return;
      box.innerHTML = `<div class="suggestion-item empty"><span class="suggestion-sub"><i class="fa-solid fa-triangle-exclamation text-amber"></i> Online search failed (${escapeHtml(err2.message)}). Please try again later.</span></div>`;
      return;
    }
  }
  if (token !== Search.onlineToken) return;
  places = places.filter(p => p.lat > 5.7 && p.lat < 10 && p.lon > 79.3 && p.lon < 82.1)
    .filter((p, i, arr) => !arr.slice(0, i).some(o => o.name === p.name && haversineKm(o.lat, o.lon, p.lat, p.lon) < 2));
  Search.results = places.map((p, i) => ({ type: 'place', place: p, district: findDistrict(p.district), score: 100 - i, title: p.name, sub: placeSub(p), si: '', badge: p.typeLabel }));
  Search.highlighted = Search.results.length ? 0 : -1;
  if (!Search.results.length) {
    box.innerHTML = `<div class="suggestion-item empty"><span class="suggestion-sub"><i class="fa-solid fa-circle-info"></i> OpenStreetMap has no place called “${escapeHtml(query)}” in Sri Lanka either. Try a nearby town, or use the 📍 location button.</span></div>`;
    return;
  }
  renderSuggestions(query);
  box.insertAdjacentHTML('beforeend', '<div class="suggestion-item empty attribution"><span class="suggestion-sub">Results © OpenStreetMap contributors</span></div>');
  $('district-search').focus();
}

function clearSearch() {
  $('district-search').value = '';
  $('clear-search').classList.add('hidden');
  $('search-suggestions').classList.add('hidden');
  Search.results = [];
  Search.query = '';
  Search.onlineToken++;
}

function nearestDistrict(lat, lon) {
  let best = null;
  SRI_LANKA_DISTRICTS.forEach(d => {
    const km = haversineKm(lat, lon, d.lat, d.lon);
    if (!best || km < best.km) best = { district: d, km };
  });
  return best;
}

// Closest named place in the gazetteer (towns/villages, not admin areas)
function nearestGazetteerPlace(lat, lon) {
  if (Gazetteer.status !== 'ready') return null;
  let best = null;
  const cosLat = Math.cos(lat * Math.PI / 180);
  for (const p of Gazetteer.places) {
    if ('gael'.includes(p.type)) continue;
    const dy = p.lat - lat, dx = (p.lon - lon) * cosLat;
    const d2 = dx * dx + dy * dy;
    if (!best || d2 < best.d2) best = { place: p, d2 };
  }
  return best ? { place: best.place, km: Math.sqrt(best.d2) * 111.2 } : null;
}

function useMyLocation() {
  const btn = $('geo-location-btn');
  if (!('geolocation' in navigator)) {
    showToast('Your browser does not support location services.', 'error');
    return;
  }
  btn.classList.add('locating');
  btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
  const done = () => { btn.classList.remove('locating'); btn.innerHTML = '<i class="fa-solid fa-crosshairs"></i>'; };
  navigator.geolocation.getCurrentPosition(async (pos) => {
    const { latitude, longitude } = pos.coords;
    const inSL = latitude > 5.7 && latitude < 10 && longitude > 79.3 && longitude < 82.1;
    if (!inSL) {
      done();
      const near = nearestDistrict(latitude, longitude);
      selectDistrictAndZoom(near.district, { toast: false });
      showToast(`You seem to be outside Sri Lanka – showing the nearest district, ${near.district.name}.`, 'warning', 5000);
      return;
    }
    try { await Gazetteer.load(); } catch { /* still works without village names */ }
    done();
    const district = districtAt(latitude, longitude);
    const near = nearestGazetteerPlace(latitude, longitude);
    const nearName = near && near.km < 8 ? near.place.name : '';
    selectPlace({
      name: nearName ? `Near ${nearName}` : 'My location', lat: latitude, lon: longitude, district: district.name,
      type: 'gps', ds: near && near.km < 8 ? near.place.ds : '', near: nearName
    }, { toast: false });
    showToast(`📍 Showing the forecast for your exact location${nearName ? ` (≈${near.km.toFixed(1)} km from ${nearName})` : ''}, ${district.name} District`, 'success', 4500);
  }, (err) => {
    done();
    const msgs = {
      1: 'Location permission was denied. Allow location access in your browser settings, or search for your town or village instead.',
      2: 'Your location could not be determined right now. Try searching for your town or village instead.',
      3: 'Finding your location took too long. Please try again.'
    };
    showToast(msgs[err.code] || 'Could not get your location.', 'error', 6000);
  }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 300000 });
}

