// 19. Favourites & saved locations (Feature 7) – districts and exact places
// ==========================================================================
function currentFavItem() { return AppState.selectedPlace || AppState.selectedDistrict.name; }
function favLabel(f) { return typeof f === 'string' ? f : f.name; }
function isFavorite(item = currentFavItem()) { const k = favKey(item); return AppState.favorites.some(f => favKey(f) === k); }

function toggleFavorite(item = currentFavItem()) {
  const k = favKey(item);
  const label = favLabel(item);
  if (isFavorite(item)) {
    AppState.favorites = AppState.favorites.filter(f => favKey(f) !== k);
    showToast(`${label} removed from favourites`, 'info', 2000);
  } else {
    if (AppState.favorites.length >= 12) { showToast('You can save up to 12 favourites. Remove one first.', 'warning'); return; }
    AppState.favorites.push(typeof item === 'string' ? item : sanitizePlace(item));
    showToast(`⭐ ${label} saved to favourites`, 'success', 2000);
  }
  store.set(KEYS.favorites, AppState.favorites);
  persistPlaceCaches();
  renderFavorites();
  updateFavoriteButtons();
  render25DistrictsGrid();
}

function updateFavoriteButtons() {
  const fav = isFavorite();
  const label = favLabel(currentFavItem());
  ['spotlight-favorite-toggle', 'hero-fav-toggle'].forEach(id => {
    const b = $(id);
    if (!b) return;
    b.innerHTML = `<i class="fa-${fav ? 'solid' : 'regular'} fa-star"></i>`;
    b.classList.toggle('is-fav', fav);
    b.setAttribute('aria-pressed', String(fav));
    b.title = fav ? 'Remove from favourites' : 'Save to favourites';
  });
  const add = $('add-current-favorite-btn');
  add.innerHTML = fav
    ? `<i class="fa-solid fa-heart"></i> ${escapeHtml(label)} saved`
    : `<i class="fa-regular fa-heart"></i> Save ${escapeHtml(label)}`;
  add.classList.toggle('is-fav', fav);
}

function renderFavorites() {
  const list = $('favorites-scroll-list');
  if (!AppState.favorites.length) {
    list.innerHTML = '<span class="favorites-empty"><i class="fa-regular fa-star"></i> No saved places yet. Tap the ☆ star on any district, town or village (or “Save”) to pin it here for one-click access.</span>';
    return;
  }
  list.innerHTML = '';
  const currentKey = favKey(currentFavItem());
  AppState.favorites.forEach(f => {
    const isPlace = typeof f !== 'string';
    const name = favLabel(f);
    const data = isPlace ? AppState.placeWeatherCache[placeKey(f)] : AppState.districtWeatherCache[f];
    const w = data ? getWeatherInfo(data.weatherCode, data.isDay) : null;
    const chip = document.createElement('div');
    chip.className = `favorite-chip ${favKey(f) === currentKey ? 'active' : ''}`;
    chip.setAttribute('role', 'button');
    chip.setAttribute('tabindex', '0');
    chip.title = isPlace ? `${f.name} · ${placeTypeLabel(f)} · ${f.district} District` : `${f} District`;
    chip.innerHTML = `
      ${w ? `<i class="fa-solid ${w.icon}" style="color:${w.color}"></i>` : '<i class="fa-solid fa-location-dot"></i>'}
      <span>${escapeHtml(name)}${isPlace ? `<small class="fav-district">${escapeHtml(f.district)}</small>` : ''}</span>
      <span class="fav-temp">${data ? formatTemp(data.currentTemp) : '--'}</span>
      <button class="fav-remove-btn" aria-label="Remove ${escapeHtml(name)} from favourites" title="Remove"><i class="fa-solid fa-xmark"></i></button>`;
    const open = () => (isPlace ? selectPlace(f) : selectDistrictAndZoom(findDistrict(f)));
    chip.addEventListener('click', (e) => {
      if (e.target.closest('.fav-remove-btn')) { toggleFavorite(f); return; }
      open();
    });
    chip.addEventListener('keydown', (e) => { if (e.key === 'Enter') open(); });
    list.appendChild(chip);
  });
}

function initFavorites() {
  $('add-current-favorite-btn').addEventListener('click', () => toggleFavorite());
  $('spotlight-favorite-toggle').addEventListener('click', () => toggleFavorite());
  $('hero-fav-toggle').addEventListener('click', () => toggleFavorite());
  renderFavorites();
  updateFavoriteButtons();
}

