// ==========================================================================
// 21. Marine bulletin (live waves + wind per sea area)
// ==========================================================================
function seaStateFromWave(h) {
  if (!isNum(h)) return ['Unknown', 'text-muted'];
  if (h < 0.1) return ['Calm (glassy)', 'text-emerald'];
  if (h < 0.5) return ['Smooth', 'text-emerald'];
  if (h < 1.25) return ['Slight', 'text-emerald'];
  if (h < 2.5) return ['Moderate', 'text-amber'];
  if (h < 4) return ['Rough', 'text-rose'];
  if (h < 6) return ['Very rough', 'text-rose'];
  return ['High', 'text-rose'];
}

function renderMarineSector(key) {
  const live = AppState.marineCache[key];
  const fallback = MARINE_SECTORS[key];
  if (live && isNum(live.wave)) {
    const [state, cls] = seaStateFromWave(live.waveMax ?? live.wave);
    $('marine-condition').textContent = state;
    $('marine-condition').className = `m-val ${cls}`;
    $('marine-wind').textContent = `${formatWind(live.wind)} ${getWindDirectionCardinal(live.windDeg)} (gusts ${formatWind(live.gusts)})`;
    $('marine-waves').textContent = `${live.wave.toFixed(1)} m now · up to ${(live.waveMax ?? live.wave).toFixed(1)} m today${isNum(live.period) ? ` · ${Math.round(live.period)} s period` : ''}`;
    const rough = (live.waveMax ?? live.wave) >= 2.5 || live.gusts >= 50;
    const thunder = live.code >= 95;
    let note = rough
      ? 'Rough seas expected. Naval and fishing communities should avoid venturing into this sea area.'
      : thunder ? 'Thundershowers likely over the sea. Fishers should take precautions against lightning.'
        : 'No significant marine hazard expected. Always follow Met Department sea-area bulletins before departure.';
    $('marine-note').innerHTML = `<i class="fa-solid fa-circle-info"></i> ${note} <span class="marine-src">Live model data · ${colomboTime(live.fetchedAt)}</span>`;
  } else if (fallback) {
    $('marine-condition').textContent = fallback.condition;
    $('marine-condition').className = 'm-val text-amber';
    $('marine-wind').textContent = fallback.wind;
    $('marine-waves').textContent = fallback.waves;
    $('marine-note').innerHTML = `<i class="fa-solid fa-circle-info"></i> ${fallback.note} <span class="marine-src">Typical conditions – live sea data unavailable</span>`;
  }
}

function syncMarineSectorToDistrict(district) {
  const key = DISTRICT_SEA_SECTOR[district.name];
  if (key && $('sea-sector-select').value !== key) {
    $('sea-sector-select').value = key;
  }
  renderMarineSector($('sea-sector-select').value);
}

function initMarineSector() {
  $('sea-sector-select').addEventListener('change', (e) => renderMarineSector(e.target.value));
}

// ==========================================================================
// 22. Clothing & activity recommendations (Feature 12)
// ==========================================================================
const DRY_ZONE = ['Jaffna', 'Kilinochchi', 'Mannar', 'Vavuniya', 'Mullaitivu', 'Anuradhapura', 'Polonnaruwa', 'Trincomalee', 'Batticaloa', 'Ampara', 'Puttalam', 'Hambantota', 'Monaragala'];
const COASTAL = Object.keys(DISTRICT_SEA_SECTOR);

function climateZone(district) {
  const elev = elevationMeters(district);
  if (elev >= 900) return 'Hill Country (Montane)';
  if (elev >= 300) return 'Mid-Country';
  const dn = district.zoneName || district.name;
  if (DRY_ZONE.includes(dn)) return COASTAL.includes(dn) ? 'Dry Zone Coastal' : 'Dry Zone';
  return COASTAL.includes(dn) ? 'Wet Zone Coastal' : 'Wet Zone Lowland';
}

function computeLifestyle(district, x) {
  const next6 = (x.hourly || []).slice(0, 6);
  const rain6 = Math.max(0, ...next6.map(h => h.rainProb));
  const thunder = x.weatherCode >= 95 || next6.some(h => h.code >= 95);
  const uv = Math.max(x.uvIndex, x.uvMax);
  const outfit = [];
  const add = (icon, text) => outfit.push({ icon, text });

  if (x.feelsLike >= 32) add('fa-shirt', 'Light, loose cotton or linen');
  else if (x.feelsLike >= 24) add('fa-shirt', 'T-shirt & breathable clothes');
  else if (x.feelsLike >= 18) add('fa-vest', 'Light long sleeves or a thin jacket');
  else add('fa-mitten', 'Warm jacket / sweater');
  if (rain6 >= 60 || thunder) add('fa-umbrella', 'Umbrella or rain jacket');
  else if (rain6 >= 35) add('fa-umbrella', 'Pocket umbrella, just in case');
  if (rain6 >= 50) add('fa-shoe-prints', 'Slippers / quick-dry sandals');
  if (uv >= 6 && x.isDay && x.cloudPct < 90) add('fa-glasses', 'Sunglasses & SPF 30+ sunscreen');
  if (uv >= 8 && x.isDay) add('fa-hat-cowboy', 'Hat or cap for midday sun');
  if (x.humidity >= 80 && x.feelsLike >= 28) add('fa-bottle-water', 'Carry water – very humid');
  if (x.windSpeed >= 30) add('fa-wind', 'Windproof layer');
  if (!x.isDay && x.currentTemp < 22) add('fa-moon', 'Extra layer for the cool night');

  const s = (v) => Math.round(clamp(v, 0, 10));
  const scores = {
    beach: s(10 - rain6 / 18 - (thunder ? 4 : 0) - (x.windSpeed > 30 ? 2 : 0) - (x.currentTemp < 24 ? 3 : 0) - (uv >= 11 ? 1 : 0) - (COASTAL.includes(district.zoneName || district.name) ? 0 : 1)),
    hiking: s(10 - rain6 / 20 - (thunder ? 4 : 0) - (x.feelsLike > 38 ? 2.5 : x.feelsLike > 34 ? 1 : 0) - (x.visibilityKm < 4 ? 2 : 0) - (x.windSpeed > 40 ? 2 : 0)),
    sports: s(10 - rain6 / 15 - (thunder ? 5 : 0) - (x.feelsLike > 40 ? 3 : x.feelsLike > 36 ? 1.5 : 0)),
    laundry: s(10 - rain6 / 12 - (x.humidity > 85 ? 2 : x.humidity > 75 ? 1 : 0) - (x.cloudPct > 80 ? 1.5 : 0) + (x.windSpeed > 15 ? 0.5 : 0) - (x.isDay ? 0 : 3))
  };
  return { zone: climateZone(district), outfit, scores, rain6, thunder };
}

function renderLifestyle(district, x) {
  const l = computeLifestyle(district, x);
  $('clothing-climate-type').textContent = l.zone;
  $('outfit-pills-row').innerHTML = l.outfit.map(o => `<span class="outfit-pill"><i class="fa-solid ${o.icon}"></i> ${o.text}</span>`).join('');
  const label = v => v >= 8 ? 'Great' : v >= 6 ? 'Good' : v >= 4 ? 'Fair' : 'Poor';
  const cls = v => v >= 7 ? 'score-good' : v >= 4 ? 'score-ok' : 'score-poor';
  [['act-beach', 'beach'], ['act-hiking', 'hiking'], ['act-sports', 'sports'], ['act-laundry', 'laundry']].forEach(([id, k]) => {
    const v = l.scores[k];
    const el = $(id);
    el.textContent = `${v}/10 · ${label(v)}`;
    el.className = `act-score ${cls(v)}`;
  });
}

// ==========================================================================
// 23. Air quality (Feature 14)
// ==========================================================================
const AQI_LEVELS = [
  { max: 50, label: 'Good', color: '#10b981', title: 'Air quality is good', advice: 'Air pollution poses little or no risk. Great for outdoor activities.' },
  { max: 100, label: 'Moderate', color: '#eab308', title: 'Air quality is acceptable', advice: 'Unusually sensitive people should consider reducing long or heavy outdoor exertion.' },
  { max: 150, label: 'Unhealthy for sensitive groups', color: '#f97316', title: 'Sensitive groups may be affected', advice: 'Children, older adults and people with asthma or heart conditions should limit prolonged outdoor exertion.' },
  { max: 200, label: 'Unhealthy', color: '#ef4444', title: 'Unhealthy air', advice: 'Everyone should reduce prolonged outdoor exertion. Consider wearing a mask in traffic.' },
  { max: 300, label: 'Very unhealthy', color: '#a855f7', title: 'Very unhealthy air', advice: 'Avoid outdoor exertion. Keep windows closed and use an N95 mask outdoors.' },
  { max: Infinity, label: 'Hazardous', color: '#9f1239', title: 'Hazardous air', advice: 'Health emergency conditions. Stay indoors.' }
];
function aqiLevel(aqi) { return AQI_LEVELS.find(l => aqi <= l.max) || AQI_LEVELS[0]; }

function renderAQI(district) {
  const a = district.isPlace !== undefined ? aqiFor(district) : AppState.aqiCache[district.name];
  const card = document.querySelector('.aqi-card');
  if (!a || !isNum(a.aqi)) {
    $('aqi-badge').textContent = AppState.hasLoadedOnce ? 'Unavailable' : 'Loading…';
    $('aqi-score-num').textContent = '--';
    $('aqi-health-title').textContent = AppState.hasLoadedOnce ? 'Air-quality data unavailable' : 'Loading air quality…';
    $('aqi-health-advice').textContent = AppState.hasLoadedOnce ? 'We could not reach the air-quality service. It will retry on the next refresh.' : '';
    ['aqi-pm25', 'aqi-pm10', 'aqi-no2', 'aqi-o3'].forEach(id => { $(id).textContent = '--'; });
    card.style.removeProperty('--aqi-color');
    return;
  }
  const lvl = aqiLevel(a.aqi);
  card.style.setProperty('--aqi-color', lvl.color);
  $('aqi-badge').textContent = `${lvl.label} (${a.aqi})`;
  $('aqi-badge').style.background = lvl.color;
  $('aqi-badge').style.color = '#fff';
  $('aqi-score-num').textContent = a.aqi;
  $('aqi-health-title').textContent = `${lvl.title} in ${district.name}`;
  $('aqi-health-advice').textContent = lvl.advice;
  const f = v => isNum(v) ? `${v.toFixed(1)} µg/m³` : '--';
  $('aqi-pm25').textContent = f(a.pm25);
  $('aqi-pm10').textContent = f(a.pm10);
  $('aqi-no2').textContent = f(a.no2);
  $('aqi-o3').textContent = f(a.o3);
}

// ==========================================================================
// 24. Historical climate & comparisons (Feature 16)
// ==========================================================================
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function monsoonSeason(monthIdx) {
  if (monthIdx >= 4 && monthIdx <= 8) return { name: 'South-West Monsoon (Yala)', desc: 'Moist winds from the Indian Ocean bring rain to western & southern slopes; the north and east stay dry and windy.' };
  if (monthIdx === 9 || monthIdx === 10) return { name: 'Second Inter-Monsoon', desc: 'Afternoon thunderstorms island-wide. Often the wettest period, with risk of floods and landslides.' };
  if (monthIdx === 11 || monthIdx <= 1) return { name: 'North-East Monsoon (Maha)', desc: 'Rain mainly for the north, east and hill country; the south-west becomes drier and sunnier.' };
  return { name: 'First Inter-Monsoon', desc: 'Hot, humid days with evening thundershowers, mostly in the south-west and hill country.' };
}

async function loadHistoricalData(district) {
  const hkey = district.key || district.name;
  if (AppState.historyCache[hkey]) return AppState.historyCache[hkey];
  const saved = store.get(KEYS.history + hkey);
  const thisYear = new Date().getFullYear();
  if (saved && saved.endYear === thisYear - 1) {
    AppState.historyCache[hkey] = saved;
    return saved;
  }
  const startYear = thisYear - 10, endYear = thisYear - 1;
  const url = `${API.archive}?latitude=${(+district.lat).toFixed(4)}&longitude=${(+district.lon).toFixed(4)}&start_date=${startYear}-01-01&end_date=${endYear}-12-31&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&timezone=Asia%2FColombo`;
  const json = await fetchJSON(url, { timeout: 30000, retries: 1 });
  const d = json.daily;
  const sums = MONTHS.map(() => ({ max: 0, min: 0, n: 0, rain: 0, recordHigh: -99, recordHighDate: '', wettest: 0, wettestDate: '' }));
  const byDate = {};
  d.time.forEach((t, i) => {
    const m = Number(t.slice(5, 7)) - 1;
    const mx = d.temperature_2m_max[i], mn = d.temperature_2m_min[i], r = d.precipitation_sum[i];
    if (isNum(mx) && isNum(mn)) { sums[m].max += mx; sums[m].min += mn; sums[m].n++; }
    if (isNum(r)) sums[m].rain += r;
    if (isNum(mx) && mx > sums[m].recordHigh) { sums[m].recordHigh = mx; sums[m].recordHighDate = t; }
    if (isNum(r) && r > sums[m].wettest) { sums[m].wettest = r; sums[m].wettestDate = t; }
    byDate[t] = [mx, mn, r];
  });
  const years = endYear - startYear + 1;
  const monthly = sums.map(s => ({
    meanMax: s.n ? s.max / s.n : null, meanMin: s.n ? s.min / s.n : null, rain: s.rain / years,
    recordHigh: s.recordHigh, recordHighDate: s.recordHighDate, wettest: s.wettest, wettestDate: s.wettestDate
  }));
  // Same calendar day for each of the last 3 years
  const md = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Colombo' }).slice(5);
  const sameDay = [endYear, endYear - 1, endYear - 2].map(y => {
    const v = byDate[`${y}-${md}`];
    return v ? { year: y, max: v[0], min: v[1], rain: v[2] } : null;
  }).filter(Boolean);
  const result = { startYear, endYear, monthly, sameDay, savedAt: Date.now() };
  AppState.historyCache[hkey] = result;
  store.set(KEYS.history + hkey, result);
  return result;
}

async function renderHistorical(district) {
  const m = colomboMonthIndex();
  const season = monsoonSeason(m);
  $('hist-monsoon-season').textContent = season.name;
  $('hist-monsoon-desc').textContent = season.desc;
  $('historical-district-label').textContent = district.name;
  const hkey = district.key || district.name;
  const stillSelected = () => activeLoc().key === hkey;

  const hist = AppState.historyCache[hkey];
  if (!hist) {
    $('historical-card').classList.add('is-loading');
    $('hist-status').innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Loading 10 years of history…';
    try {
      await loadHistoricalData(district);
    } catch (err) {
      console.warn('History fetch failed', err);
      if (!stillSelected()) return;
      $('historical-card').classList.remove('is-loading');
      $('hist-status').innerHTML = '<i class="fa-solid fa-triangle-exclamation text-amber"></i> Historical data is unavailable right now (needs internet). It will load automatically when you are back online.';
      ['hist-temp-anomaly', 'hist-rain-norm', 'hist-last-year'].forEach(id => { $(id).textContent = '--'; });
      return;
    }
    if (!stillSelected()) return; // user moved on
  }
  fillHistorical(district, AppState.historyCache[hkey]);
}

function fillHistorical(district, hist) {
  const m = colomboMonthIndex();
  const norm = hist.monthly[m];
  const x = district.isPlace !== undefined ? weatherFor(district) : AppState.districtWeatherCache[district.name];
  $('historical-card').classList.remove('is-loading');
  $('hist-status').innerHTML = `<i class="fa-solid fa-database"></i> ${hist.startYear}–${hist.endYear} averages for ${district.name} (ERA5 reanalysis via Open-Meteo archive)`;

  if (x && isNum(norm.meanMax)) {
    const diff = x.todayMax - norm.meanMax;
    const word = Math.abs(diff) < 0.5 ? 'close to normal' : diff > 0 ? 'above normal' : 'below normal';
    $('hist-temp-anomaly').textContent = `${formatTempDiff(diff)} · ${word}`;
    $('hist-temp-anomaly').className = `hist-val ${Math.abs(diff) < 0.5 ? '' : diff > 0 ? 'text-rose' : 'text-blue'}`;
    $('hist-temp-desc').innerHTML = `Today's forecast high ${formatTemp(x.todayMax)} vs ${MONTHS[m]} average high <strong>${formatTemp(norm.meanMax, 1)}</strong>. Record ${MONTHS[m]} high: ${formatTemp(norm.recordHigh, 1)} (${norm.recordHighDate.slice(0, 4)}).`;
  }
  const week = x ? (x.sevenDay || []).reduce((s, d) => s + (d.rainSum || 0), 0) : 0;
  $('hist-rain-norm').textContent = `${formatRain(norm.rain)} / month`;
  $('hist-rain-desc').innerHTML = x
    ? `Next 7 days forecast: <strong>${formatRain(week)}</strong> (${Math.round(week / Math.max(norm.rain, 1) * 100)}% of a normal ${MONTHS[m]}). Wettest ${MONTHS[m]} day: ${formatRain(norm.wettest)} (${norm.wettestDate.slice(0, 4)}).`
    : 'Average total rainfall for this month.';

  if (hist.sameDay.length) {
    const ly = hist.sameDay[0];
    $('hist-last-year').textContent = `${formatTemp(ly.max)} / ${formatTemp(ly.min)} · ${formatRain(ly.rain)}`;
    $('hist-last-year-desc').innerHTML = hist.sameDay.map(s => `<span class="hist-chip">${s.year}: ${formatRawNum(s.max)}° / ${formatRawNum(s.min)}°, ${formatRain(s.rain)}</span>`).join(' ');
  }
  renderHistoricalChart(hist);
}

function renderHistoricalChart(hist) {
  if (!chartsAvailable('historicalChart')) return;
  const t = chartTheme();
  const m = colomboMonthIndex();
  if (AppState.charts.history) AppState.charts.history.destroy();
  AppState.charts.history = new Chart($('historicalChart'), {
    data: {
      labels: MONTHS,
      datasets: [
        { type: 'bar', label: `Avg monthly rain (${AppState.rainUnit})`, data: hist.monthly.map(x => +rainValue(x.rain).toFixed(AppState.rainUnit === 'in' ? 1 : 0)), yAxisID: 'y', backgroundColor: hist.monthly.map((_, i) => i === m ? '#6366f1' : (t.dark ? 'rgba(99,102,241,0.35)' : 'rgba(99,102,241,0.3)')), borderRadius: 5, order: 2 },
        { type: 'line', label: `Avg high (°${AppState.unit.toUpperCase()})`, data: hist.monthly.map(x => +cToUnit(x.meanMax).toFixed(1)), yAxisID: 'y1', borderColor: '#f43f5e', backgroundColor: '#f43f5e', tension: 0.35, pointRadius: hist.monthly.map((_, i) => i === m ? 6 : 3), order: 1 },
        { type: 'line', label: `Avg low (°${AppState.unit.toUpperCase()})`, data: hist.monthly.map(x => +cToUnit(x.meanMin).toFixed(1)), yAxisID: 'y1', borderColor: '#38bdf8', backgroundColor: '#38bdf8', tension: 0.35, pointRadius: hist.monthly.map((_, i) => i === m ? 6 : 3), order: 1 }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false, interaction: { mode: 'index', intersect: false },
      plugins: { legend: { labels: { color: t.text, boxWidth: 12 } }, tooltip: t.tooltip },
      scales: {
        x: { grid: { color: t.grid }, ticks: { color: t.text } },
        y: { position: 'left', beginAtZero: true, grid: { color: t.grid }, ticks: { color: t.text }, title: { display: true, text: AppState.rainUnit, color: t.text } },
        y1: { position: 'right', grid: { display: false }, ticks: { color: t.text, callback: v => `${v}°` } }
      }
    }
  });
}

// ==========================================================================
// 25. Severe weather alerts & notifications (Feature 9)
// ==========================================================================
const LANDSLIDE_DISTRICTS = ['Badulla', 'Kandy', 'Kegalle', 'Kalutara', 'Matale', 'Matara', 'Nuwara Eliya', 'Ratnapura', 'Galle', 'Hambantota', 'Colombo', 'Gampaha', 'Kurunegala', 'Monaragala'];
const LEVEL_RANK = { red: 3, amber: 2, yellow: 1, green: 0 };

function computeAlerts() {
  const all = SRI_LANKA_DISTRICTS.map(d => [d, AppState.districtWeatherCache[d.name]]).filter(([, x]) => x);
  const alerts = [];
  const names = list => list.map(([d]) => d.name);
  const listText = arr => arr.length > 6 ? `${arr.slice(0, 6).join(', ')} and ${arr.length - 6} more` : arr.join(', ');
  const rain24 = x => (x.hourly || []).slice(0, 24).reduce((s, h) => s + (h.rainAmount || 0), 0);

  const thunder = all.filter(([, x]) => x.weatherCode >= 95 || (x.hourly || []).slice(0, 12).some(h => h.code >= 95));
  if (thunder.length) alerts.push({
    id: 'thunder', level: thunder.some(([, x]) => x.weatherCode >= 96 || (x.hourly || []).slice(0, 12).some(h => h.code >= 96)) ? 'red' : 'amber', icon: 'fa-cloud-bolt', title: 'Thunderstorm & Lightning Advisory', districts: names(thunder),
    message: `Thunderstorms are likely within the next 12 hours in ${listText(names(thunder))}.`,
    advice: ['Stay indoors or in a closed vehicle during lightning.', 'Avoid open fields, hilltops, tall trees and water bodies.', 'Unplug electrical appliances; avoid using wired phones.']
  });

  const heavy = all.filter(([, x]) => rain24(x) >= 50 || (x.sevenDay[0] && x.sevenDay[0].rainSum >= 50));
  if (heavy.length) {
    const veryHeavy = heavy.filter(([, x]) => rain24(x) >= 100);
    alerts.push({
      id: 'heavy-rain', level: veryHeavy.length ? 'red' : 'amber', icon: 'fa-cloud-showers-heavy', title: veryHeavy.length ? 'Very Heavy Rain Warning' : 'Heavy Rain Advisory', districts: names(heavy),
      message: `More than 50 mm of rain is forecast in the next 24 hours for ${listText(names(heavy))}${veryHeavy.length ? `; over 100 mm possible in ${listText(names(veryHeavy))}` : ''}.`,
      advice: ['Expect flash floods in low-lying areas and on roads.', 'Do not cross flowing water on foot or by vehicle.', 'Follow DMC (117) instructions if evacuation is advised.']
    });
  }

  const slide = all.filter(([d, x]) => LANDSLIDE_DISTRICTS.includes(d.name) && rain24(x) >= 75);
  if (slide.length) alerts.push({
    id: 'landslide', level: slide.some(([, x]) => rain24(x) >= 100) ? 'red' : 'amber', icon: 'fa-mountain', title: 'Landslide Risk (NBRO threshold)', districts: names(slide),
    message: `Forecast rain exceeds 75 mm in 24 h – the NBRO "be alert" level – in landslide-prone ${listText(names(slide))}.`,
    advice: ['Watch for cracks in walls/ground, tilting trees or muddy springs.', 'Move to a safer place if you see signs of slope movement.', 'NBRO landslide hotline: 011 2588946.']
  });

  const wind = all.filter(([, x]) => x.gusts >= 50 || x.gustMaxToday >= 60);
  if (wind.length) alerts.push({
    id: 'wind', level: wind.some(([, x]) => x.gustMaxToday >= 75) ? 'red' : 'amber', icon: 'fa-wind', title: 'Strong Wind Advisory', districts: names(wind),
    message: `Wind gusts of 50–${Math.round(Math.max(...wind.map(([, x]) => Math.max(x.gusts, x.gustMaxToday))))} km/h expected in ${listText(names(wind))}.`,
    advice: ['Secure loose roofing sheets and outdoor items.', 'Take care when driving two-wheelers on exposed roads.', 'Fishing and naval communities should check sea-area bulletins.']
  });

  const heat = all.filter(([, x]) => x.feelsLike >= 39 || (x.hourly || []).slice(0, 12).some(h => h.temp >= 35));
  if (heat.length) alerts.push({
    id: 'heat', level: heat.some(([, x]) => x.feelsLike >= 45) ? 'red' : 'yellow', icon: 'fa-temperature-arrow-up', title: 'Heat Index Caution', districts: names(heat),
    message: `It will feel very hot (heat index 39 °C+) in ${listText(names(heat))}.`,
    advice: ['Drink water often, even if you are not thirsty.', 'Limit strenuous outdoor work between 11 am and 3 pm.', 'Check on elderly people, children and pets.']
  });

  const uv = all.filter(([, x]) => x.uvMax >= 11);
  if (uv.length) alerts.push({
    id: 'uv', level: 'yellow', icon: 'fa-sun', title: 'Extreme UV Index', districts: names(uv),
    message: `UV index reaches 11+ (extreme) around midday in ${listText(names(uv))}.`,
    advice: ['Use SPF 30+ sunscreen and reapply every 2 hours.', 'Wear a hat and sunglasses; seek shade at midday.']
  });

  const aqiBad = SRI_LANKA_DISTRICTS.filter(d => (AppState.aqiCache[d.name] || {}).aqi > 100).map(d => d.name);
  if (aqiBad.length) alerts.push({
    id: 'aqi', level: aqiBad.some(n => AppState.aqiCache[n].aqi > 150) ? 'amber' : 'yellow', icon: 'fa-smog', title: 'Poor Air Quality', districts: aqiBad,
    message: `Air quality is unhealthy for sensitive groups in ${listText(aqiBad)}.`,
    advice: ['People with asthma should keep inhalers handy.', 'Reduce outdoor exercise near heavy traffic.']
  });

  if (window.V4) { try { alerts.push(...V4.floodAlerts()); } catch (e) { console.warn('flood alerts', e); } }
  alerts.sort((a, b) => LEVEL_RANK[b.level] - LEVEL_RANK[a.level]);
  return alerts;
}

function updateAlerts() {
  const alerts = computeAlerts();
  const previous = AppState.currentAlerts.map(a => a.id);
  AppState.currentAlerts = alerts;
  const card = $('advisory-card');
  const top = alerts[0];
  const season = monsoonSeason(colomboMonthIndex());
  card.classList.remove('level-red', 'level-amber', 'level-yellow', 'level-green');

  if (!AppState.hasLoadedOnce) return;
  if (top) {
    card.classList.add(`level-${top.level}`);
    $('advisory-icon').className = `fa-solid ${top.icon}`;
    $('advisory-level').textContent = `${top.level === 'red' ? 'WARNING' : 'ADVISORY'} · ${top.title}`;
    $('advisory-text').textContent = `${top.message}${alerts.length > 1 ? ` (+${alerts.length - 1} more alert${alerts.length > 2 ? 's' : ''} – open the Alerts Center)` : ''}`;
  } else {
    card.classList.add('level-green');
    $('advisory-icon').className = 'fa-solid fa-circle-check';
    $('advisory-level').textContent = 'NO SEVERE WEATHER EXPECTED';
    $('advisory-text').textContent = `No thunderstorm, heavy-rain, wind or heat thresholds are forecast across the 25 districts in the next 24 hours. Season: ${season.name}.`;
  }
  $('advisory-timestamp').textContent = `Updated ${colomboTime(AppState.lastFetchedAt || Date.now())}${AppState.dataSource !== 'live' ? ' · from saved data' : ''}`;
  $('alerts-count-badge').textContent = alerts.length;
  $('alerts-count-badge').classList.toggle('hidden', !alerts.length);

  // New alerts → toast + browser notification (only for favourites / selected district)
  const fresh = alerts.filter(a => !previous.includes(a.id) && a.level !== 'yellow');
  maybeNotify(fresh);
  if (!$('alerts-modal-backdrop').classList.contains('hidden')) renderAlertsCenter();
}

function maybeNotify(alerts) {
  if (!alerts.length) return;
  const mine = [AppState.selectedDistrict.name, ...AppState.favorites.map(f => (typeof f === 'string' ? f : f.district))];
  const notified = store.get(KEYS.notified, {}) || {};
  const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Colombo' });
  alerts.forEach(a => {
    const affected = a.districts.filter(n => mine.includes(n));
    if (!affected.length) return;
    const key = `${today}:${a.id}:${affected.join(',')}`;
    if (notified[key]) return;
    notified[key] = 1;
    showToast(`${a.title}: ${affected.join(', ')}`, 'warning', 7000);
    if (AppState.notifyEnabled && 'Notification' in window && Notification.permission === 'granted') {
      try { new Notification(`ලංකාweather · ${a.title}`, { body: `${affected.join(', ')} – ${a.advice[0]}`, icon: 'sl-flag.svg', tag: a.id }); }
      catch (e) { console.warn('Notification failed', e); }
    }
  });
  // keep the notified log small
  Object.keys(notified).forEach(k => { if (!k.startsWith(today)) delete notified[k]; });
  store.set(KEYS.notified, notified);
}

function renderAlertsCenter() {
  const body = $('alerts-modal-body');
  const alerts = AppState.currentAlerts;
  const season = monsoonSeason(colomboMonthIndex());
  const levelText = { red: 'Warning', amber: 'Advisory', yellow: 'Caution', green: 'All clear' };
  const notifSupported = 'Notification' in window;
  const notifState = !notifSupported ? 'unsupported' : Notification.permission;

  body.innerHTML = `
    <div class="alerts-notify-row">
      <div><strong><i class="fa-solid fa-bell"></i> Browser notifications</strong>
        <p>${!notifSupported ? 'Your browser does not support notifications.' : notifState === 'denied' ? 'Blocked in browser settings. Allow notifications for this site to enable.' : 'Get a pop-up when a new warning affects your selected or favourite districts (while this page is open).'}</p></div>
      <button id="toggle-notify-btn" class="btn-alerts-modal" ${!notifSupported || notifState === 'denied' ? 'disabled' : ''}>
        ${AppState.notifyEnabled && notifState === 'granted' ? '<i class="fa-solid fa-bell-slash"></i> Turn off' : '<i class="fa-solid fa-bell"></i> Turn on'}
      </button>
    </div>
    ${alerts.length ? alerts.map(a => `
      <div class="alert-item level-${a.level}">
        <div class="alert-item-head">
          <i class="fa-solid ${a.icon}"></i>
          <div><span class="alert-level-tag">${levelText[a.level]}</span><h4>${a.title}</h4></div>
        </div>
        <p>${a.message}</p>
        <div class="alert-districts">${a.districts.map(n => `<button class="alert-district-chip" data-district="${n}">${n}</button>`).join('')}</div>
        <ul class="alert-advice">${a.advice.map(t => `<li>${t}</li>`).join('')}</ul>
      </div>`).join('') : `
      <div class="alert-item level-green">
        <div class="alert-item-head"><i class="fa-solid fa-circle-check"></i><div><span class="alert-level-tag">All clear</span><h4>No severe weather expected</h4></div></div>
        <p>None of the 25 districts cross thunderstorm, heavy-rain, landslide, wind, heat, UV or air-quality thresholds in the next 24 hours.</p>
      </div>`}
    <div class="alert-item level-info">
      <div class="alert-item-head"><i class="fa-solid fa-calendar-days"></i><div><span class="alert-level-tag">Season</span><h4>${season.name}</h4></div></div>
      <p>${season.desc}</p>
    </div>
    <div class="alerts-hotlines">
      <a href="tel:117"><i class="fa-solid fa-phone"></i> DMC <strong>117</strong></a>
      <a href="tel:1990"><i class="fa-solid fa-truck-medical"></i> Suwa Seriya <strong>1990</strong></a>
      <a href="tel:0112686686"><i class="fa-solid fa-tower-broadcast"></i> Met Dept <strong>011 2686686</strong></a>
      <a href="tel:0112588946"><i class="fa-solid fa-mountain"></i> NBRO <strong>011 2588946</strong></a>
      <a href="tel:119"><i class="fa-solid fa-shield-halved"></i> Police <strong>119</strong></a>
    </div>
    <p class="alerts-disclaimer"><i class="fa-solid fa-circle-info"></i> These alerts are generated automatically from Open-Meteo forecast data using common Sri Lankan thresholds. They are not official warnings – always follow the <a href="https://meteo.gov.lk" target="_blank" rel="noopener">Department of Meteorology</a> and <a href="https://www.dmc.gov.lk" target="_blank" rel="noopener">DMC</a>.</p>`;

  body.querySelectorAll('.alert-district-chip').forEach(chip => chip.addEventListener('click', () => {
    closeModal('alerts-modal-backdrop');
    selectDistrictAndZoom(findDistrict(chip.dataset.district));
    $('interactive-map-section').scrollIntoView({ behavior: 'smooth' });
  }));
  const nb = $('toggle-notify-btn');
  if (nb) nb.addEventListener('click', async () => {
    if (AppState.notifyEnabled && Notification.permission === 'granted') {
      AppState.notifyEnabled = false;
    } else {
      const perm = await Notification.requestPermission();
      AppState.notifyEnabled = perm === 'granted';
      if (perm === 'granted') {
        try { new Notification('ලංකාweather alerts enabled', { body: 'You will be notified about severe weather for your saved districts.', icon: 'sl-flag.svg' }); } catch { /* ignore */ }
      } else showToast('Notifications were not allowed.', 'warning');
    }
    store.set(KEYS.notify, AppState.notifyEnabled);
    renderAlertsCenter();
  });
}

// ==========================================================================
// 26. Modals (shared)
// ==========================================================================
let lastFocusBeforeModal = null;
function openModal(id) {
  lastFocusBeforeModal = document.activeElement;
  const m = $(id);
  m.classList.remove('hidden');
  document.body.classList.add('modal-open');
  const focusable = m.querySelector('input, select, button:not(.modal-close-btn)') || m.querySelector('button');
  setTimeout(() => focusable && focusable.focus(), 50);
}
function closeModal(id) {
  $(id).classList.add('hidden');
  if (!document.querySelector('.modal-backdrop:not(.hidden)')) document.body.classList.remove('modal-open');
  if (lastFocusBeforeModal && lastFocusBeforeModal.focus) lastFocusBeforeModal.focus();
}
function initModals() {
  const pairs = [
    ['ai-assistant-btn', 'ai-modal-backdrop', 'ai-modal-close'],
    ['nav-compare-btn', 'compare-modal-backdrop', 'compare-modal-close'],
    ['view-alerts-center-btn', 'alerts-modal-backdrop', 'alerts-modal-close']
  ];
  pairs.forEach(([openId, modalId, closeId]) => {
    $(openId).addEventListener('click', () => {
      if (modalId === 'alerts-modal-backdrop') renderAlertsCenter();
      if (modalId === 'compare-modal-backdrop') prepareComparison();
      openModal(modalId);
    });
    $(closeId).addEventListener('click', () => closeModal(modalId));
    $(modalId).addEventListener('click', (e) => { if (e.target.id === modalId) closeModal(modalId); });
  });
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const open = [...document.querySelectorAll('.modal-backdrop:not(.hidden)')].pop();
    if (open) closeModal(open.id);
  });
}

// ==========================================================================
// 27. Built-in weather assistant (Feature 11)
// ==========================================================================
function findDistrictsInText(text) {
  const t = normalise(text);
  const found = [];
  const push = (d, via) => { if (d && !found.some(f => f.district.name === d.name)) found.push({ district: d, via }); };
  const hits = [];
  SRI_LANKA_DISTRICTS.forEach(d => {
    const i = t.indexOf(normalise(d.name));
    if (i >= 0) hits.push([i, d, null]);
    if (text.includes(d.sinhala)) hits.push([text.indexOf(d.sinhala), d, null]);
  });
  SEARCH_PLACES.forEach(p => {
    const key = normalise(p.name.replace(/\(.*\)/, '')).trim();
    const i = key.length > 3 ? t.indexOf(key) : -1;
    if (i >= 0) hits.push([i, findDistrict(p.district), p.name, isFinite(p.lat) ? { name: p.name, lat: p.lat, lon: p.lon, district: p.district, type: 'p', si: p.sinhala } : null]);
  });
  // Any town, suburb or city from the full gazetteer (approximate word position)
  const words = t.split(/\s+/);
  Gazetteer.findInText(text).forEach(([wi, p]) => {
    const pos = words.slice(0, wi).join(' ').length + (wi ? 1 : 0);
    if (!hits.some(h => h[0] === pos)) hits.push([pos, findDistrict(p.district), p.name, p]);
  });
  hits.sort((a, b) => a[0] - b[0]).forEach(([, d, via, place]) => {
    if (!d) return;
    if (via && found.some(f => f.via === via)) return;
    // a named town/village counts as its own location (so "Ella vs Haputale" compares the two places)
    if (place) { found.push({ district: d, via, place }); return; }
    push(d, via);
  });
  return found;
}

function aiAnswer(question) {
  const q = question.toLowerCase();
  const mentioned = findDistrictsInText(question);
  let target, placeName, x;
  const m0 = mentioned[0];
  if (m0) {
    const px = m0.place && AppState.placeWeatherCache[placeKey(m0.place)];
    target = px ? placeLoc(sanitizePlace(m0.place) || m0.place, px) : m0.district;
    x = px || AppState.districtWeatherCache[m0.district.name];
    placeName = escapeHtml(m0.via ? `${m0.via} (${m0.district.name} District)` : m0.district.name);
    // fetch the exact forecast for next time if we only had the district one
    if (m0.place && !px && navigator.onLine !== false) loadPlaceWeather([sanitizePlace(m0.place)].filter(Boolean)).catch(() => {});
  } else {
    target = activeLoc();
    x = weatherFor(target) || AppState.districtWeatherCache[target.district.name];
    placeName = target.isPlace ? `${escapeHtml(target.name)} (${target.district.name} District)` : target.name;
  }
  const all = SRI_LANKA_DISTRICTS.map(d => [d, AppState.districtWeatherCache[d.name]]).filter(([, v]) => v);
  const has = (...words) => words.some(w => q.includes(w));

  if (!x) return 'I am still loading the latest forecast. Please try again in a few seconds.';

  if (/^(hi|hello|hey|ayubowan|ආයුබෝවන්|vanakkam|good (morning|afternoon|evening))\b/.test(q.trim())) {
    return `Ayubowan! 🙏 Right now ${escapeHtml(target.name)} is ${formatTemp(x.currentTemp)} with ${getWeatherInfo(x.weatherCode, x.isDay).label.toLowerCase()}. Ask me about rain, clothing, hiking, the sea, air quality or any district.`;
  }
  if (has('help', 'what can you')) {
    return 'I answer using the live forecast loaded on this page. Try: <em>“Will it rain in Kandy this evening?”</em>, <em>“What should I wear in Nuwara Eliya?”</em>, <em>“Compare Colombo and Jaffna”</em>, <em>“Which district is the hottest?”</em>, <em>“Is it safe to climb Sigiriya?”</em>, <em>“How is the sea at Mirissa?”</em>, or ask about any town, e.g. <em>“Will it rain in Maharagama?”</em>';
  }

  // Comparisons
  if (mentioned.length >= 2 && has('compare', ' vs', 'versus', ' or ', 'between', 'difference', 'warmer', 'cooler', 'better')) {
    const locOf = (m) => {
      const px = m.place && AppState.placeWeatherCache[placeKey(m.place)];
      return px ? { name: m.place.name, x: px, v: `p:${placeKey(m.place)}` } : { name: m.via ? `${m.via} (${m.district.name})` : m.district.name, x: AppState.districtWeatherCache[m.district.name], v: m.district.name };
    };
    const [la, lb] = mentioned.slice(0, 2).map(locOf);
    const a = { name: escapeHtml(la.name) }, b = { name: escapeHtml(lb.name) };
    const xa = la.x, xb = lb.x;
    if (!xa || !xb) return 'I am still loading the latest forecast. Please try again in a few seconds.';
    const cmpA = la.v, cmpB = lb.v;
    const diff = xa.currentTemp - xb.currentTemp;
    const drier = xa.rainProb <= xb.rainProb ? a : b;
    return `<strong>${a.name}</strong>: ${formatTemp(xa.currentTemp)}, ${getWeatherInfo(xa.weatherCode, xa.isDay).label.toLowerCase()}, ${Math.round(xa.rainProb)}% rain chance.<br><strong>${b.name}</strong>: ${formatTemp(xb.currentTemp)}, ${getWeatherInfo(xb.weatherCode, xb.isDay).label.toLowerCase()}, ${Math.round(xb.rainProb)}% rain chance.<br>${Math.abs(diff) < 0.5 ? `${a.name} and ${b.name} are about the same temperature.` : `${a.name} is ${formatTempDiff(Math.abs(diff)).replace('+', '')} ${diff >= 0 ? 'warmer' : 'cooler'}.`} ${Math.abs(xa.rainProb - xb.rainProb) < 5 ? 'Both have a similar chance of rain.' : `${drier.name} looks drier today.`}${cmpA !== cmpB ? ` <button class="ai-inline-btn" data-compare="${escapeHtml(cmpA)}|${escapeHtml(cmpB)}">Open full comparison</button>` : ''}`;
  }

  // Rankings across the island
  const rank = (fn, label, fmt, desc = true) => {
    const sorted = [...all].sort((p, r) => desc ? fn(r[1]) - fn(p[1]) : fn(p[1]) - fn(r[1]));
    return `${label}: ${sorted.slice(0, 3).map(([d, v], i) => `${i + 1}. <strong>${d.name}</strong> (${fmt(v)})`).join(', ')}.`;
  };
  if (has('hottest', 'warmest')) return rank(v => v.currentTemp, 'Hottest districts right now', v => formatTemp(v.currentTemp));
  if (has('coolest', 'coldest')) return rank(v => v.currentTemp, 'Coolest districts right now', v => formatTemp(v.currentTemp), false);
  if (has('wettest', 'rainiest', 'most rain')) return rank(v => v.rainProb * 1000 + v.precipToday, 'Wettest outlook today', v => `${Math.round(v.rainProb)}%, ${formatRain(v.precipToday)}`);
  if (has('driest', 'least rain', 'sunniest')) return rank(v => v.rainProb * 1000 + v.precipToday, 'Driest outlook today', v => `${Math.round(v.rainProb)}% rain chance`, false);
  if (has('windiest')) return rank(v => v.windSpeed, 'Windiest districts now', v => formatWind(v.windSpeed));

  const life = computeLifestyle(target, x);
  const w = getWeatherInfo(x.weatherCode, x.isDay);

  if (has('wear', 'outfit', 'cloth', 'dress', 'pack', 'jacket')) {
    return `For ${placeName} (${formatTemp(x.currentTemp)}, feels like ${formatTemp(x.feelsLike)}, ${x.humidity}% humidity) I'd suggest: ${life.outfit.map(o => o.text.toLowerCase()).join('; ')}.`;
  }
  if (has('rain', 'umbrella', 'shower', 'wet', 'drizzle', 'flood')) {
    const wet = nextRainHour(x, 50);
    const heavy = (x.hourly || []).slice(0, 24).reduce((s, h) => s + h.rainAmount, 0);
    let ans = `${placeName}: ${Math.round(x.rainProb)}% chance of rain today, about ${formatRain(heavy)} expected over the next 24 hours. `;
    ans += wet ? `Rain is most likely from around <strong>${hourLabel(wet.isoTime)}</strong> (${wet.rainProb}%).` : 'No hour in the next day goes above a 50% chance – it looks mostly dry. ';
    if (life.thunder) ans += ' ⚡ Thunderstorms are possible, so stay indoors during lightning.';
    if (heavy >= 50) ans += ' Heavy rain could cause flooding in low-lying areas.';
    return ans;
  }
  if (has('hike', 'hiking', 'climb', 'trek', 'sigiriya', 'adam', 'sri pada', 'ella rock', 'horton', 'safe', 'travel', 'trip', 'visit')) {
    const s = life.scores.hiking;
    const best = (x.hourly || []).slice(1, 12).filter(h => h.isDay).sort((a, b) => (a.rainProb + Math.max(0, a.temp - 30) * 5) - (b.rainProb + Math.max(0, b.temp - 30) * 5))[0];
    return `Outdoor/hiking score for ${placeName}: <strong>${s}/10</strong>. ${w.label}, ${formatTemp(x.currentTemp)}, ${Math.round(life.rain6)}% max rain chance in the next 6 h${life.thunder ? ', thunderstorms possible ⚡' : ''}. ${best ? `Best window in daylight: around <strong>${hourLabel(best.isoTime)}</strong>. ` : ''}${s >= 7 ? 'Good conditions – start early and carry water.' : s >= 4 ? 'Doable, but carry rain gear and watch the sky.' : 'Not recommended right now – consider another time.'}`;
  }
  if (has('sea', 'beach', 'swim', 'surf', 'wave', 'marine', 'fish', 'boat', 'whale', 'snorkel', 'coast')) {
    const key = DISTRICT_SEA_SECTOR[target.zoneName || target.name];
    if (!key) return `${placeName} is in an inland district. The beach score there is ${life.scores.beach}/10, but for sea conditions ask about a coastal place like Mirissa, Negombo, Arugam Bay or Trincomalee.`;
    const m = AppState.marineCache[key];
    const sea = m && isNum(m.wave) ? `Waves around ${m.wave.toFixed(1)} m (up to ${(m.waveMax ?? m.wave).toFixed(1)} m), sea state <strong>${seaStateFromWave(m.waveMax ?? m.wave)[0].toLowerCase()}</strong>, wind ${formatWind(m.wind)} ${getWindDirectionCardinal(m.windDeg)}.` : 'Live wave data is unavailable right now.';
    return `Sea area <em>${MARINE_SECTOR_POINTS[key].label}</em>: ${sea} Beach score for ${placeName}: <strong>${life.scores.beach}/10</strong>. ${m && (m.waveMax ?? m.wave) >= 2 ? 'Swimming is risky – stay between the flags or avoid the water.' : 'Swim only at lifeguarded beaches and watch for rip currents.'}`;
  }
  if (has('monsoon', 'season', 'yala', 'maha')) {
    const s = monsoonSeason(colomboMonthIndex());
    return `We're in the <strong>${s.name}</strong>. ${s.desc} ${escapeHtml(target.name)} is in the ${climateZone(target)} zone.`;
  }
  if (has('uv', 'sunscreen', 'sunburn', 'sun ')) {
    return `UV in ${placeName}: ${getUVDescription(x.uvIndex)} now, peaking at ${getUVDescription(x.uvMax)} today. ${x.uvMax >= 8 ? 'Use SPF 30+, a hat and sunglasses; avoid midday sun (11 am – 3 pm).' : 'Moderate protection is enough.'}`;
  }
  if (has('air', 'aqi', 'pollution', 'pm2', 'smog', 'dust')) {
    const a = target.isPlace ? aqiFor(target) : AppState.aqiCache[target.name];
    if (!a || !isNum(a.aqi)) return 'Air-quality data is not available right now.';
    const l = aqiLevel(a.aqi);
    return `Air quality in ${escapeHtml(target.name)}: US AQI <strong>${a.aqi} (${l.label})</strong>, PM2.5 ${a.pm25?.toFixed(1)} µg/m³. ${l.advice}`;
  }
  if (has('sunrise', 'sunset', 'daylight', 'moon', 'poya', 'dark')) {
    const moon = getMoonInfo();
    return `${escapeHtml(target.name)}: sunrise ${x.sunriseISO ? colomboTime(x.sunriseISO) : '--'}, sunset ${x.sunsetISO ? colomboTime(x.sunsetISO) : '--'} (${x.daylightSec ? formatDuration(x.daylightSec) : '--'} of daylight). Moon: ${moon.emoji} ${moon.name}, ${moon.illumination}% lit. Next Poya ≈ ${colomboDate(moon.nextFull, { weekday: 'long' })}.`;
  }
  if (has('wind', 'storm', 'gust', 'cyclone')) {
    return `Wind in ${placeName}: ${formatWind(x.windSpeed)} from the ${x.windDirection}, gusts up to ${formatWind(Math.max(x.gusts, x.gustMaxToday))} today – ${windStrengthWord(x.windSpeed)}.${x.gustMaxToday >= 60 ? ' Secure loose objects.' : ''}`;
  }
  if (has('tomorrow', 'week', 'weekend', 'next few days', 'forecast', 'days')) {
    const days = (x.sevenDay || []).slice(q.includes('tomorrow') ? 1 : 0, q.includes('tomorrow') ? 2 : 7);
    return `${placeName} outlook:<br>${days.map((d, i) => `• <strong>${dayLabel(d.isoDate, q.includes('tomorrow') ? 1 : i)}</strong>: ${getWeatherInfo(d.code).label}, ${formatTemp(d.maxTemp)} / ${formatTemp(d.minTemp)}, ${Math.round(d.rainProb)}% rain`).join('<br>')}`;
  }
  if (has('laundry', 'dry clothes', 'washing')) {
    return `Laundry-drying score for ${placeName}: <strong>${life.scores.laundry}/10</strong> (humidity ${x.humidity}%, ${Math.round(life.rain6)}% rain chance in next 6 h).`;
  }
  if (has('cricket', 'sport', 'match', 'run', 'jog', 'exercise')) {
    return `Outdoor sports score for ${placeName}: <strong>${life.scores.sports}/10</strong>. Feels like ${formatTemp(x.feelsLike)}${life.thunder ? ', thunderstorms possible ⚡' : ''}. ${x.feelsLike >= 36 ? 'Play early morning or evening and hydrate well.' : ''}`;
  }
  if (has('hot', 'cold', 'temperature', 'warm', 'humid', 'weather', 'now', 'today', 'how')) {
    return buildDistrictReport(target, x).summary;
  }
  return `${buildDistrictReport(target, x).summary}<br><span class="ai-hint">Tip: ask about rain, clothing, hiking, the sea, air quality, or compare two districts.</span>`;
}

function addChatMessage(html, who = 'bot') {
  const log = $('ai-chat-log');
  const msg = document.createElement('div');
  msg.className = `ai-msg ai-${who}`;
  msg.innerHTML = `<div class="msg-avatar"><i class="fa-solid ${who === 'bot' ? 'fa-robot' : 'fa-user'}"></i></div><div class="msg-bubble">${html}</div>`;
  log.appendChild(msg);
  log.scrollTop = log.scrollHeight;
  msg.querySelectorAll('[data-compare]').forEach(b => b.addEventListener('click', () => {
    const [a, c] = b.dataset.compare.split('|');
    closeModal('ai-modal-backdrop');
    prepareComparison(a, c);
    openModal('compare-modal-backdrop');
  }));
  return msg;
}

function askAssistant(question) {
  const q = question.trim();
  if (!q) return;
  addChatMessage(escapeHtml(q), 'user');
  const typing = addChatMessage('<span class="typing-dots"><span></span><span></span><span></span></span>', 'bot');
  const started = Date.now();
  const missing = findDistrictsInText(q).filter(m => m.place && !AppState.placeWeatherCache[placeKey(m.place)]).map(m => sanitizePlace(m.place)).filter(Boolean).slice(0, 3);
  const preload = missing.length && navigator.onLine !== false
    ? Promise.race([loadPlaceWeather(missing).catch(() => {}), new Promise(r => setTimeout(r, 8000))])
    : Promise.resolve();
  preload.then(() => new Promise(r => setTimeout(r, Math.max(0, 450 + Math.random() * 350 - (Date.now() - started))))).then(() => {
    let answer;
    try { answer = aiAnswer(q); } catch (e) { console.error(e); answer = 'Sorry, something went wrong while reading the forecast. Please try again.'; }
    typing.querySelector('.msg-bubble').innerHTML = answer;
    typing.querySelectorAll('[data-compare]').forEach(b => b.addEventListener('click', () => {
      const [a, c] = b.dataset.compare.split('|');
      closeModal('ai-modal-backdrop');
      prepareComparison(a, c);
      openModal('compare-modal-backdrop');
    }));
    $('ai-chat-log').scrollTop = $('ai-chat-log').scrollHeight;
  });
}

function initAssistant() {
  $('ai-chat-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const input = $('ai-user-input');
    askAssistant(input.value);
    input.value = '';
  });
  document.querySelectorAll('.ai-chip').forEach(chip => chip.addEventListener('click', () => askAssistant(chip.dataset.prompt)));
}

// ==========================================================================
// 28. City-to-city comparison (Feature 20)
// ==========================================================================
// Compare entries are either a district name or "p:<placeKey>" for a town/village with a loaded forecast
function compareEntry(value) {
  if (String(value).startsWith('p:')) {
    const x = AppState.placeWeatherCache[value.slice(2)];
    if (!x) return null;
    const d = findDistrict(x.parentDistrict);
    return { name: x.district, sub: `${x.placeType} · ${x.parentDistrict} District`, lat: x.lat, lon: x.lon, x, aqi: (AppState.placeAqiCache[value.slice(2)] || AppState.aqiCache[d.name] || {}).aqi };
  }
  const d = findDistrict(value);
  if (!d) return null;
  return { name: d.name, sub: `${d.sinhala} · ${d.province}`, lat: d.lat, lon: d.lon, x: AppState.districtWeatherCache[d.name], aqi: (AppState.aqiCache[d.name] || {}).aqi };
}

function prepareComparison(a, b) {
  const s1 = $('compare-city-1'), s2 = $('compare-city-2');
  const placeOpts = Object.entries(AppState.placeWeatherCache).filter(([, x]) => !x.approx && x.district)
    .sort((p, q) => p[1].district.localeCompare(q[1].district))
    .map(([k, x]) => `<option value="p:${escapeHtml(k)}">📍 ${escapeHtml(x.district)} (${escapeHtml(x.parentDistrict)})</option>`).join('');
  const districtOpts = [...SRI_LANKA_DISTRICTS].sort((p, q) => p.name.localeCompare(q.name))
    .map(d => `<option value="${d.name}">${d.name} – ${d.sinhala}</option>`).join('');
  const html = (placeOpts ? `<optgroup label="Towns &amp; villages">${placeOpts}</optgroup>` : '') + `<optgroup label="Districts">${districtOpts}</optgroup>`;
  const firstTime = !s1.options.length;
  s1.innerHTML = html;
  s2.innerHTML = html;
  if (firstTime) {
    s1.addEventListener('change', renderComparison);
    s2.addEventListener('change', renderComparison);
    $('compare-swap-btn').addEventListener('click', () => {
      [s1.value, s2.value] = [s2.value, s1.value];
      renderComparison();
    });
  }
  const sel = AppState.selectedPlace && AppState.placeWeatherCache[placeKey(AppState.selectedPlace)];
  const current = sel && !sel.approx ? `p:${placeKey(AppState.selectedPlace)}` : AppState.selectedDistrict.name;
  const has = (v) => v && compareEntry(v);
  s1.value = has(a) ? a : current;
  const favVals = AppState.favorites.map(f => (typeof f === 'string' ? f : `p:${placeKey(f)}`)).filter(v => v !== s1.value && has(v));
  s2.value = has(b) ? b : (favVals[0] || (s1.value === 'Nuwara Eliya' ? 'Colombo' : 'Nuwara Eliya'));
  if (!s1.value) s1.value = AppState.selectedDistrict.name;
  if (!s2.value) s2.value = 'Nuwara Eliya';
  renderComparison();
}

function renderComparison() {
  const ds = [$('compare-city-1').value, $('compare-city-2').value].map(compareEntry);
  const wrap = $('compare-results-wrapper');
  if (ds.some(e => !e || !e.x)) { wrap.innerHTML = '<p class="compare-empty">Weather data is still loading…</p>'; return; }
  const xs = ds.map(e => e.x);
  const aqis = ds.map(e => e.aqi);

  const rows = [
    ['Feels like', x => formatTemp(x.feelsLike), x => x.feelsLike],
    ['High / Low', x => `${formatTemp(x.todayMax)} / ${formatTemp(x.todayMin)}`, null],
    ['Humidity', x => `${x.humidity}%`, x => x.humidity],
    ['Wind', x => `${formatWind(x.windSpeed)} ${x.windDirection}`, x => x.windSpeed],
    ['Rain chance', x => `${Math.round(x.rainProb)}%`, x => x.rainProb],
    ['Rain today', x => formatRain(x.precipToday), x => x.precipToday],
    ['UV max', x => getUVDescription(x.uvMax), x => x.uvMax],
    ['Pressure', x => formatPressure(x.surfacePressure), null],
    ['Sunrise / Sunset', x => `${x.sunriseISO ? colomboTime(x.sunriseISO) : '--'} / ${x.sunsetISO ? colomboTime(x.sunsetISO) : '--'}`, null]
  ];

  wrap.innerHTML = xs.map((x, i) => {
    const w = getWeatherInfo(x.weatherCode, x.isDay);
    const other = xs[1 - i];
    const aqi = aqis[i];
    return `<div class="compare-city-card">
      <div class="compare-card-head">
        <div><h4>${escapeHtml(ds[i].name)}</h4><span class="compare-si" lang="si">${escapeHtml(ds[i].sub)}</span></div>
        <i class="fa-solid ${w.icon}" style="color:${w.color}; font-size:2rem"></i>
      </div>
      <div class="compare-temp-big">${formatTemp(x.currentTemp)}</div>
      <div class="compare-cond">${w.label}</div>
      ${rows.map(([label, fmt, val]) => {
        const higher = val && val(x) > val(other);
        return `<div class="compare-metric-row"><span>${label}</span><strong class="${higher ? 'is-higher' : ''}">${fmt(x)}${higher ? ' <i class="fa-solid fa-caret-up"></i>' : ''}</strong></div>`;
      }).join('')}
      <div class="compare-metric-row"><span>Air quality</span><strong>${isNum(aqi) ? `${aqi} · ${aqiLevel(aqi).label}` : '--'}</strong></div>
    </div>`;
  }).join('');

  const diff = xs[0].currentTemp - xs[1].currentTemp;
  const rainDiff = xs[0].rainProb - xs[1].rainProb;
  $('compare-summary').innerHTML = `<i class="fa-solid fa-lightbulb text-amber"></i> <strong>${escapeHtml(ds[0].name)}</strong> is ${Math.abs(diff) < 0.5 ? 'about the same temperature as' : `${formatTempDiff(diff).replace(/^[+−]/, '')} ${diff > 0 ? 'warmer than' : 'cooler than'}`} <strong>${escapeHtml(ds[1].name)}</strong> right now, and ${Math.abs(rainDiff) < 10 ? 'has a similar chance of rain' : `${rainDiff > 0 ? 'more' : 'less'} likely to see rain (${Math.round(xs[0].rainProb)}% vs ${Math.round(xs[1].rainProb)}%)`}. ${haversineKm(ds[0].lat, ds[0].lon, ds[1].lat, ds[1].lon).toFixed(0)} km apart.`;

  if (!chartsAvailable('compareChart')) return;
  if (window.V6 && V6.compareChart) { V6.safe('compare-chart', () => V6.compareChart(ds, xs)); return; }
  const t = chartTheme();
  if (AppState.charts.compare) AppState.charts.compare.destroy();
  const hours = xs[0].hourly.slice(0, 24);
  AppState.charts.compare = new Chart($('compareChart'), {
    type: 'line',
    data: {
      labels: hours.map((h, i) => i === 0 ? 'Now' : hourLabel(h.isoTime)),
      datasets: xs.map((x, i) => ({
        label: `${ds[i].name} (°${AppState.unit.toUpperCase()})`, data: x.hourly.slice(0, 24).map(h => +cToUnit(h.temp).toFixed(1)),
        borderColor: i ? '#818cf8' : '#38bdf8', backgroundColor: i ? 'rgba(129,140,248,0.12)' : 'rgba(56,189,248,0.12)', fill: true, tension: 0.35, pointRadius: 2
      }))
    },
    options: {
      responsive: true, maintainAspectRatio: false, interaction: { mode: 'index', intersect: false },
      plugins: { legend: { labels: { color: t.text, boxWidth: 12 } }, tooltip: t.tooltip, title: { display: true, text: 'Next 24 hours – temperature', color: t.text } },
      scales: { x: { grid: { color: t.grid }, ticks: { color: t.text, maxTicksLimit: 8, maxRotation: 0 } }, y: { grid: { color: t.grid }, ticks: { color: t.text, callback: v => `${v}°` } } }
    }
  });
}

// ==========================================================================
// 29. Dynamic weather animations & backgrounds (Feature 15)
// ==========================================================================
const Ambient = {
  canvas: null, ctx: null, w: 0, h: 0, dpr: 1, scene: null, particles: [], raf: null, last: 0, flash: 0, nextFlash: 0,
  reduced: window.matchMedia('(prefers-reduced-motion: reduce)').matches,

  init() {
    this.canvas = $('weather-ambient-canvas');
    if (!this.canvas || !this.canvas.getContext) return;
    this.ctx = this.canvas.getContext('2d');
    this.resize();
    window.addEventListener('resize', () => { this.resize(); this.build(); });
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.stop(); else this.start(); });
    window.matchMedia('(prefers-reduced-motion: reduce)').addEventListener?.('change', (e) => { this.reduced = e.matches; this.start(); });
  },
  resize() {
    this.dpr = Math.min(window.devicePixelRatio || 1, 1.5);
    this.w = window.innerWidth; this.h = window.innerHeight;
    this.canvas.width = this.w * this.dpr; this.canvas.height = this.h * this.dpr;
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  },
  sceneFor(x) {
    const c = x.weatherCode;
    if (c >= 95) return 'storm';
    if ([65, 81, 82].includes(c)) return 'heavy-rain';
    if ([61, 63, 80].includes(c)) return 'rain';
    if (c >= 51 && c <= 55) return 'drizzle';
    if (c === 45 || c === 48) return 'fog';
    if (c === 3) return x.isDay ? 'cloudy' : 'cloudy-night';
    if (c === 2) return x.isDay ? 'partly-day' : 'partly-night';
    return x.isDay ? 'clear-day' : 'clear-night';
  },
  setSceneFromData(x) {
    if (!this.ctx) return;
    const scene = this.sceneFor(x);
    document.body.dataset.weatherScene = scene;
    if (scene === this.scene) return;
    this.scene = scene;
    this.build();
    this.start();
  },
  refreshColors() { if (this.reduced) this.drawFrame(0); },
  rand(a, b) { return a + Math.random() * (b - a); },
  build() {
    const s = this.scene, P = [];
    const area = (this.w * this.h) / (1400 * 900);
    const count = n => Math.round(n * clamp(area, 0.35, 1.6));
    if (['rain', 'heavy-rain', 'storm', 'drizzle'].includes(s)) {
      const n = count(s === 'drizzle' ? 70 : s === 'rain' ? 140 : 230);
      for (let i = 0; i < n; i++) P.push({ k: 'drop', x: this.rand(0, this.w), y: this.rand(-this.h, this.h), len: s === 'drizzle' ? this.rand(6, 10) : this.rand(12, 22), v: s === 'drizzle' ? this.rand(250, 380) : this.rand(650, 1000), a: this.rand(0.25, 0.6) });
    }
    if (['clear-night', 'partly-night', 'cloudy-night'].includes(s)) {
      for (let i = 0; i < count(s === 'clear-night' ? 140 : 70); i++) P.push({ k: 'star', x: this.rand(0, this.w), y: this.rand(0, this.h * 0.8), r: this.rand(0.4, 1.6), ph: this.rand(0, Math.PI * 2), sp: this.rand(0.6, 2) });
    }
    if (['cloudy', 'cloudy-night', 'partly-day', 'partly-night', 'storm', 'heavy-rain', 'rain'].includes(s)) {
      const n = s.startsWith('partly') ? 4 : 7;
      for (let i = 0; i < n; i++) P.push({ k: 'cloud', x: this.rand(-200, this.w), y: this.rand(20, this.h * 0.45), s: this.rand(0.7, 1.6), v: this.rand(6, 18), a: this.rand(0.05, 0.12) });
    }
    if (['clear-day', 'partly-day'].includes(s)) {
      for (let i = 0; i < count(35); i++) P.push({ k: 'mote', x: this.rand(0, this.w), y: this.rand(0, this.h), r: this.rand(1, 3), vx: this.rand(-8, 8), vy: this.rand(-12, -3), a: this.rand(0.1, 0.35), ph: this.rand(0, 6) });
    }
    if (s === 'fog') {
      for (let i = 0; i < 6; i++) P.push({ k: 'fog', y: this.rand(0, this.h), v: this.rand(8, 22), off: this.rand(0, this.w), a: this.rand(0.05, 0.1), hgt: this.rand(80, 180) });
    }
    this.particles = P;
    this.nextFlash = performance.now() + this.rand(3000, 7000);
  },
  start() {
    this.stop();
    if (!this.ctx || document.hidden) return;
    if (this.reduced) { this.drawFrame(0); return; }
    this.last = performance.now();
    const loop = (now) => {
      const dt = Math.min(0.05, (now - this.last) / 1000);
      this.last = now;
      this.drawFrame(dt, now);
      this.raf = requestAnimationFrame(loop);
    };
    this.raf = requestAnimationFrame(loop);
  },
  stop() { cancelAnimationFrame(this.raf); this.raf = null; },
  drawFrame(dt, now = performance.now()) {
    const { ctx, w, h } = this;
    const dark = AppState.theme === 'dark';
    ctx.clearRect(0, 0, w, h);
    const s = this.scene;

    // sun / moon glow
    if (s === 'clear-day' || s === 'partly-day') {
      const g = ctx.createRadialGradient(w * 0.85, h * 0.08, 10, w * 0.85, h * 0.08, Math.max(w, h) * 0.45);
      g.addColorStop(0, dark ? 'rgba(251,191,36,0.22)' : 'rgba(251,191,36,0.28)');
      g.addColorStop(1, 'rgba(251,191,36,0)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
      // slowly rotating rays
      ctx.save(); ctx.translate(w * 0.85, h * 0.08); ctx.rotate(now / 40000);
      ctx.fillStyle = dark ? 'rgba(251,191,36,0.035)' : 'rgba(245,158,11,0.05)';
      for (let i = 0; i < 12; i++) { ctx.rotate(Math.PI / 6); ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(Math.max(w, h), -40); ctx.lineTo(Math.max(w, h), 40); ctx.closePath(); ctx.fill(); }
      ctx.restore();
    }
    if (s && s.endsWith('night')) {
      const g = ctx.createRadialGradient(w * 0.85, h * 0.1, 5, w * 0.85, h * 0.1, 260);
      g.addColorStop(0, dark ? 'rgba(199,210,254,0.25)' : 'rgba(99,102,241,0.12)');
      g.addColorStop(1, 'rgba(199,210,254,0)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    }

    for (const p of this.particles) {
      if (p.k === 'drop') {
        p.y += p.v * dt; p.x -= p.v * dt * 0.12;
        if (p.y > h) { p.y = this.rand(-60, -10); p.x = this.rand(0, w + 100); }
        ctx.strokeStyle = dark ? `rgba(147,197,253,${p.a})` : `rgba(2,132,199,${p.a * 0.7})`;
        ctx.lineWidth = s === 'drizzle' ? 1 : 1.3;
        ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x - p.len * 0.12, p.y + p.len); ctx.stroke();
      } else if (p.k === 'star') {
        if (!dark) continue;
        const tw = 0.5 + 0.5 * Math.sin(now / 1000 * p.sp + p.ph);
        ctx.fillStyle = `rgba(255,255,255,${0.25 + tw * 0.6})`;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill();
      } else if (p.k === 'cloud') {
        p.x += p.v * dt;
        if (p.x > w + 250) p.x = -300;
        const col = dark ? `rgba(148,163,184,${p.a})` : `rgba(100,116,139,${p.a * 0.8})`;
        ctx.fillStyle = col;
        [[0, 0, 60], [50, -20, 50], [100, 0, 55], [45, 15, 55]].forEach(([dx, dy, r]) => {
          ctx.beginPath(); ctx.arc(p.x + dx * p.s, p.y + dy * p.s, r * p.s, 0, Math.PI * 2); ctx.fill();
        });
      } else if (p.k === 'mote') {
        p.x += p.vx * dt; p.y += p.vy * dt;
        if (p.y < -10) { p.y = h + 10; p.x = this.rand(0, w); }
        const a = p.a * (0.6 + 0.4 * Math.sin(now / 900 + p.ph));
        ctx.fillStyle = dark ? `rgba(253,224,71,${a})` : `rgba(245,158,11,${a * 0.8})`;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill();
      } else if (p.k === 'fog') {
        p.off = (p.off + p.v * dt) % (w * 2);
        const g = ctx.createLinearGradient(0, p.y - p.hgt / 2, 0, p.y + p.hgt / 2);
        const c = dark ? '203,213,225' : '148,163,184';
        g.addColorStop(0, `rgba(${c},0)`); g.addColorStop(0.5, `rgba(${c},${p.a})`); g.addColorStop(1, `rgba(${c},0)`);
        ctx.fillStyle = g; ctx.fillRect(-w + p.off, p.y - p.hgt / 2, w * 2, p.hgt);
      }
    }

    // lightning
    if (s === 'storm' && !this.reduced) {
      if (now > this.nextFlash) { this.flash = 1; this.nextFlash = now + this.rand(3500, 9000); }
      if (this.flash > 0) {
        ctx.fillStyle = `rgba(255,255,255,${this.flash * (dark ? 0.35 : 0.5)})`;
        ctx.fillRect(0, 0, w, h);
        this.flash = Math.max(0, this.flash - dt * 3.5);
      }
    }
  }
};

// ==========================================================================
// 30. Offline mode (Feature 18) + loading states (Feature 19)
// ==========================================================================
function setLoading(on) {
  document.body.classList.toggle('is-refreshing', on);
  $('global-loader').classList.toggle('active', on);
  $('manual-refresh-btn').classList.toggle('spinning', on);
  $('manual-refresh-btn').disabled = on;
}

function updateOfflineBanner() {
  const banner = $('offline-banner');
  const offline = navigator.onLine === false;
  const usingFallback = AppState.dataSource === 'cache' || AppState.dataSource === 'sample';
  if (!offline && !usingFallback) { banner.classList.add('hidden'); return; }
  let text;
  if (offline) {
    text = AppState.dataSource === 'sample'
      ? '<strong>You are offline</strong> and no saved weather is available yet – showing <strong>sample data</strong>. Real data will load when you reconnect.'
      : `<strong>You are offline.</strong> Showing weather saved ${AppState.lastFetchedAt ? `at ${colomboTime(AppState.lastFetchedAt)} (${timeAgo(AppState.lastFetchedAt)})` : 'earlier'}. We'll refresh automatically when you reconnect.`;
  } else {
    text = AppState.dataSource === 'sample'
      ? `<strong>Weather service unreachable</strong> (${escapeHtml(AppState.lastError || 'network error')}). Showing <strong>sample data</strong> for now.`
      : `<strong>Weather service unreachable</strong> (${escapeHtml(AppState.lastError || 'network error')}). Showing data saved ${AppState.lastFetchedAt ? timeAgo(AppState.lastFetchedAt) : 'earlier'}.`;
  }
  $('offline-banner-text').innerHTML = text;
  banner.classList.remove('hidden');
}

function initOfflineMode() {
  window.addEventListener('offline', () => {
    showToast('You are offline – showing saved weather data.', 'warning');
    updateOfflineBanner();
  });
  window.addEventListener('online', () => {
    showToast('Back online – refreshing weather…', 'success', 2500);
    refreshAllData();
  });
  $('offline-retry-btn').addEventListener('click', () => refreshAllData({ manual: true }));

  // Service worker caches the app shell so the page itself opens offline (needs http/https)
  if ('serviceWorker' in navigator && /^https?:$/.test(location.protocol)) {
    navigator.serviceWorker.register('sw.js').catch(err => console.warn('Service worker registration failed:', err));
  }
}

// ==========================================================================
// 31. Refresh pipeline
// ==========================================================================
async function refreshAllData({ isAuto = false, manual = false, silent = false } = {}) {
  if (AppState.isRefreshing) return;
  AppState.isRefreshing = true;
  if (isAuto || manual) Object.values(AppState.placeWeatherCache).forEach(x => { x.fetchedAt = Math.min(x.fetchedAt || 0, Date.now() - PLACE_FRESH_MS); });
  setLoading(true);
  startCountdownTimer();

  try {
    if (navigator.onLine === false) throw new Error('No internet connection');
    AppState.districtWeatherCache = await fetchAllDistrictsWeather();
    AppState.dataSource = 'live';
    AppState.lastFetchedAt = Date.now();
    AppState.lastError = null;
    store.set(KEYS.weather, { savedAt: AppState.lastFetchedAt, data: AppState.districtWeatherCache });
    if (isAuto && !silent) showToast('Auto-refresh complete – weather updated for all 25 districts', 'info', 3000);
    else if (manual) showToast('Weather data refreshed', 'success', 2500);
  } catch (err) {
    console.warn('Live weather fetch failed:', err);
    AppState.lastError = err.message;
    const saved = store.get(KEYS.weather);
    if (saved && saved.data && Object.keys(saved.data).length) {
      AppState.districtWeatherCache = realignCachedData(saved.data);
      AppState.dataSource = 'cache';
      AppState.lastFetchedAt = saved.savedAt;
      if (!silent) showToast(`Couldn't reach the weather service – showing data saved ${timeAgo(saved.savedAt)}.`, 'warning', 5000);
    } else {
      AppState.districtWeatherCache = Object.fromEntries(SRI_LANKA_DISTRICTS.map(d => [d.name, generateSampleData(d)]));
      AppState.dataSource = 'sample';
      AppState.lastFetchedAt = Date.now();
      showToast('Weather service unavailable and nothing saved yet – showing sample data.', 'error', 6000);
    }
  }

  AppState.hasLoadedOnce = true;
  document.body.classList.remove('app-loading');
  renderEverything();
  updateOfflineBanner();
  setLoading(false);
  if (window.V4) V4.safe('refresh', () => V4.onDataRefresh({ manual, isAuto }));
  AppState.isRefreshing = false;

  // Secondary feeds load in the background and update their own cards
  refreshSecondaryFeeds();
}

async function refreshSecondaryFeeds() {
  const online = navigator.onLine !== false;
  const [aqi, marine] = await Promise.allSettled([
    online ? fetchAllDistrictsAQI() : Promise.reject(new Error('offline')),
    online ? fetchMarineSectors() : Promise.reject(new Error('offline'))
  ]);
  if (aqi.status === 'fulfilled') { AppState.aqiCache = aqi.value; store.set(KEYS.aqi, aqi.value); }
  else { console.warn('AQI fetch failed', aqi.reason); AppState.aqiCache = store.get(KEYS.aqi, {}) || {}; }
  if (marine.status === 'fulfilled') { AppState.marineCache = marine.value; store.set(KEYS.marine, marine.value); }
  else { console.warn('Marine fetch failed', marine.reason); AppState.marineCache = store.get(KEYS.marine, {}) || {}; }
  renderAQI(activeLoc());
  renderMarineSector($('sea-sector-select').value);
  updateAlerts();
  if (window.V4) V4.safe('secondary', () => V4.onSecondaryFeeds());
  // History may have failed earlier while offline
  if (!AppState.historyCache[activeLoc().key]) renderHistorical(activeLoc());

  // Exact-location forecasts for the selected place and saved places
  const places = [AppState.selectedPlace, ...AppState.favorites.filter(f => typeof f !== 'string')].filter(Boolean);
  if (online && places.length) {
    try {
      if (await loadPlaceWeather(places)) { renderSelectedDistrictViews(); renderFavorites(); }
    } catch (err) { console.warn('Place refresh failed', err); }
  }
}

function renderEverything() {
  // Dynamic 2: update the existing map in place so colours and values can animate
  if (document.querySelector('#map-districts-group .district-path')) { applyMapLayer(); applyProvinceDimming(); renderPlaceMarker(); }
  else renderSriLankaSvgMap();
  renderSelectedDistrictViews();
  render25DistrictsGrid();
  renderFavorites();
  updateAlerts();
}

// ==========================================================================
// 32. Initialisation
// ==========================================================================
function initGlobalErrorHandling() {
  let shown = false;
  const report = (msg) => {
    console.error(msg);
    if (shown) return;
    shown = true;
    showToast('Something went wrong on this page. Try refreshing if things look wrong.', 'error', 6000);
    setTimeout(() => { shown = false; }, 15000);
  };
  window.addEventListener('error', (e) => { if (e.error) report(e.error); });
  window.addEventListener('unhandledrejection', (e) => report(e.reason));
}

async function initApp() {
  document.body.classList.add('app-loading');
  $('copyright-year').textContent = new Date().getFullYear();
  const safe = (fn, name) => { try { fn(); } catch (e) { console.error(`Init failed: ${name}`, e); } };

  safe(initGlobalErrorHandling, 'errors');
  safe(initTheme, 'theme');
  safe(initUnits, 'units');
  safe(initSearch, 'search');
  safe(initFilterControls, 'filters');
  safe(initMarineSector, 'marine');
  safe(initMapControls, 'map');
  safe(initFavorites, 'favourites');
  safe(initModals, 'modals');
  safe(initAssistant, 'assistant');
  safe(initOfflineMode, 'offline');
  safe(() => Ambient.init(), 'ambient');
  safe(startLocalClock, 'clock');
  safe(init1HourSyncEngine, 'sync');

  // Show the map + skeletons straight away; data fills in when it arrives
  renderSriLankaSvgMap();
  renderDistrictSpotlight(activeLoc());
  render25DistrictsGrid();
  renderDataStatus();
  realignCachedData(AppState.placeWeatherCache);
  if (AppState.selectedPlace) setTimeout(() => zoomToPlace(AppState.selectedPlace), 300);
  else if (AppState.selectedDistrict.name !== 'Colombo') setTimeout(() => zoomToDistrict(AppState.selectedDistrict), 300);
  // Load the 35,000-place gazetteer in the background once the page is idle
  (window.requestIdleCallback || ((fn) => setTimeout(fn, 1500)))(() => Gazetteer.load().catch(() => {}));

  await refreshAllData();
}

document.addEventListener('DOMContentLoaded', initApp);
